// The catalog is read-only data: freeze every level a caller could mutate so
// a templateData() consumer can never edit the shared definitions.
const freezeDeep = (v) => {
  if (isRecord(v) || Array.isArray(v)) {
    for (const k of Object.keys(v)) freezeDeep(v[k]);
    Object.freeze(v);
  }
  return v;
};
export const FOUNDATION_ASSEMBLY_PRESETS = freezeDeep(PRESET_ROWS.map((p) => ({ ...p })));

const findPreset = (presetOrKey) => {
  const key = typeof presetOrKey === "string" ? presetOrKey : presetOrKey?.preset_key;
  const hit = FOUNDATION_ASSEMBLY_PRESETS.find((p) => p.preset_key === key);
  if (!hit) throw new Error(`foundation assembly preset: unknown preset ${JSON.stringify(key)}`);
  return hit;
};

// Snapshot-shaped record for the dialog's existing onApply(data) lane — the
// page's prepareFoundationTemplatePatch gate validates it, mints fresh ids,
// and remaps references exactly like a stored template. Always deep-cloned:
// the catalog is frozen and shared.
export function foundationAssemblyPresetTemplateData(presetOrKey) {
  const preset = findPreset(presetOrKey);
  return deepClone({ ...preset.project_data, assembly_schema_version: 1 });
}

const COUNT_LABELS = [
  ["items", "foundation", "foundations"],
  ["walls", "wall", "walls"],
  ["poles", "pole", "poles"],
  ["wall_caps", "cap", "caps"],
  ["signage_cabinets", "cabinet", "cabinets"],
];

// Row metadata for the dialog's preset pick list.
export function describeFoundationAssemblyPreset(presetOrKey) {
  const preset = findPreset(presetOrKey);
  const data = preset.project_data || {};
  const counts = {};
  const parts = [];
  for (const [k, one, many] of COUNT_LABELS) {
    const n = Array.isArray(data[k]) ? data[k].length : 0;
    counts[k] = n;
    if (n > 0) parts.push(`${n} ${n === 1 ? one : many}`);
  }
  return {
    preset_key: preset.preset_key,
    name: preset.name,
    summary: preset.summary,
    counts,
    counts_label: parts.length ? parts.join(" · ") : "empty preset",
    total_components: Object.values(counts).reduce((a, n) => a + n, 0),
  };
}

// Direct model transform -> { patch, summary }. merge patch as
// {...prev, ...patch}.
//   mode "replace" (default): the preset runs through the template patch gate
//     — every supplied array replaces the target's (start-from semantics);
//     the project argument is validated but not otherwise needed.
//   mode "append": the preset's rows are cloned onto the existing assembly
//     (fresh collision-guarded ids, references remapped inside the clone set,
//     dependent index fields rebuilt against the merged arrays); only arrays
//     that gained rows appear in the patch.
export function applyFoundationAssemblyPreset(project, presetOrKey, {
  createId,
  appliedAt,
  mode = "replace",
} = {}) {
  if (!isRecord(project)) throw new Error("foundation assembly preset: project must be a record");
  const preset = findPreset(presetOrKey);
  const data = foundationAssemblyPresetTemplateData(preset);
  if (mode === "append") {
    const { patch, idMap, clonedCounts } = appendClonedFoundationAssemblies(project, data, { createId });
    return {
      patch,
      summary: {
        operation: "preset",
        mode: "append",
        preset_key: preset.preset_key,
        appended: clonedCounts,
        rows_added: Object.values(clonedCounts).reduce((a, n) => a + n, 0),
        id_map: Object.fromEntries(idMap),
      },
    };
  }
  if (mode !== "replace") throw new Error('foundation assembly preset: mode must be "replace" or "append"');
  return {
    patch: prepareFoundationTemplatePatch(data, { createId, appliedAt }),
    summary: { operation: "preset", mode: "replace", preset_key: preset.preset_key },
  };
}

// Sticky-totals summary model (O-096 / CMP-H05) — pure derivations for
// FoundationTotals: the separate cost/sell/margin trio, the itemized takeoff,
// and the missing-input checklist. No React, no entity access, no imports —
// identical input produces identical output, so the whole surface is
// unit-testable under Node.
//
// Held/acknowledged contract (mirrors calc + BOM surfaces):
//   • A held component keeps its acknowledged snapshot amounts; rows that
//     display them are flagged `held` so the UI can label "(saved)".
//   • A non-finite amount is unavailable — the model returns null and the UI
//     renders "Not saved"/"—"; nothing is laundered to $0 or guessed.
//   • Margin is only produced when BOTH sides are actually known — never a
//     fabricated margin on a held or projected value. When the applied
//     customer_pricing snapshot carries its own internal cost
//     (raw_subtotal), the acknowledged cost-vs-sell pair is exposed too.

const fin = (v) => typeof v === "number" && Number.isFinite(v);
const numOrNull = (v) =>
  v === undefined || v === null || v === "" ? null : Number.isFinite(Number(v)) ? Number(v) : null;
const arr = (v) => (Array.isArray(v) ? v : []);
const isRecord = (v) => !!v && typeof v === "object" && !Array.isArray(v);
const fmtQty = (n, unit, digits = 2) =>
  fin(n) ? `${n.toLocaleString(undefined, { maximumFractionDigits: digits })} ${unit}` : null;
const joinQty = (parts) => {
  const out = parts.filter((p) => typeof p === "string" && p !== "");
  return out.length ? out.join(" · ") : null;
};

// ─── Persisted split-total partition ─────────────────────────────────────────
// The same 12-field partition O-010 established (FOUNDATION_RECORD_TOTAL_FIELDS
// in builderService.js — kept in sync there; the model test asserts parity).
// total_brick_cost / total_fill_cost are subsets of total_wall_cost and are
// NEVER counted separately. A non-finite partition field is a held bucket:
// the checklist enumerates it instead of pretending the amount exists.
export const FOUNDATION_STICKY_PARTITION_FIELDS = [
  ["total_concrete_cost", "Concrete"],
  ["total_rebar_cost", "Rebar"],
  ["total_excavation_cost", "Excavation"],
  ["total_forming_materials_cost", "Forming materials"],
  ["total_labor_cost", "Labor"],
  ["total_wall_cost", "Walls"],
  ["total_pole_cost", "Poles"],
  ["total_pole_painting_cost", "Pole painting"],
  ["total_equipment_cost", "Equipment"],
  ["total_wall_cap_cost", "Wall caps"],
  ["total_signage_cabinet_cost", "Signage cabinets"],
  ["total_landscape_cost", "Site landscaping"],
];

const FOUNDATION_TYPE_LABEL = {
  spread_foot: "spread footing",
  pillar: "pillar/caisson",
};

// ─── Sticky cost / sell / margin ─────────────────────────────────────────────
//
// Sell precedence mirrors customerPricing.sourceProjectEconomics' foundation
// branch exactly: pricing engine > applied tier snapshot > price override >
// markup %. The engine side is injectable (engineResolver = the
// foundationEngineEconomics seam) so this module stays import-free; callers
// pass the real resolver when a record is wired and null otherwise.
//
// Held-safety rules:
//   • override and applied-tier sell are recorded values — they display even
//     while pricing is paused (they are the acknowledged sell, not a guess).
//   • the manual markup baseline requires the LIVE internal cost — a markup
//     projected over a held amount would fabricate a customer price, so it
//     resolves "none" while only a saved cost remains.
//   • margin requires a known cost AND a known sell; basis labels which cost
//     was compared ("live" vs "saved").

export function resolveFoundationStickySummary({
  sectionTotal = null,
  savedSectionTotal = null,
  pricingUnavailable = false,
  project = null,
  engineResolver = null,
} = {}) {
  const liveCost = fin(sectionTotal) ? sectionTotal : null;
  const savedCost = fin(savedSectionTotal) ? savedSectionTotal : null;
  const cost = liveCost !== null ? liveCost : savedCost;
  const costSource = liveCost !== null ? "live" : savedCost !== null ? "saved" : "none";

  const projectLinked = project !== null && project !== undefined;
  const markupPercent = numOrNull(project?.customer_markup_percent) ?? 0;
  const override = numOrNull(project?.customer_price_override);
  const cp = isRecord(project?.customer_pricing) ? project.customer_pricing : null;
  const tierTotal = cp?.applied === true && numOrNull(cp?.total) !== null ? numOrNull(cp.total) : null;
  const tierCost = numOrNull(cp?.raw_subtotal);

  // Manual baseline = exactly the panel/economics formula — but only against
  // the live cost AND only when the record is actually wired: with no project
  // prop the recorded markup/override are unknown, so an implicit 0% sell
  // would fabricate a customer price. Held-only cost leaves it unresolved too.
  const manualBaseline = projectLinked && liveCost !== null
    ? (override !== null && override > 0 ? override : liveCost * (1 + markupPercent / 100))
    : null;

  let sell = null;
  let sellSource = "none";
  let sellLabel = "Not recorded";

  // Engine resolution is gated on a live baseline the same way the manual
  // markup is: with the internal cost held, an engine number computed against
  // a forced-zero baseline would be a fabricated sell, not a recorded one.
  if (projectLinked && typeof engineResolver === "function" && manualBaseline !== null) {
    let wired = null;
    try {
      wired = engineResolver(project, {
        baselineSell: manualBaseline,
        internalCost: cost,
        markupPercent,
      });
    } catch {
      wired = null;
    }
    if (wired && fin(wired.customerPrice)) {
      sell = wired.customerPrice;
      sellSource = "engine";
      sellLabel = "Pricing engine";
    }
  }
  if (sell === null && tierTotal !== null) {
    sell = tierTotal;
    sellSource = "tier";
    sellLabel = `Tier ${cp.tier_number ?? "—"} applied`;
  }
  if (sell === null && override !== null && override > 0) {
    sell = override;
    sellSource = "override";
    sellLabel = "Price override";
  }
  if (sell === null && manualBaseline !== null) {
    sell = manualBaseline;
    sellSource = "markup";
    sellLabel = markupPercent > 0 ? `Markup ${markupPercent}%` : "Cost (no markup)";
  }

  const marginAmount = sell !== null && cost !== null ? sell - cost : null;
  const marginPct = marginAmount !== null && sell > 0 ? (marginAmount / sell) * 100 : null;
  const marginBasis = marginAmount !== null ? costSource : "none";

  // Acknowledged pair straight from the snapshot fields: when the applied
  // tier recorded both its sell total and the internal cost it was computed
  // on, that pair is the margin the customer actually accepted — shown as a
  // footnote when it diverges from the cost displayed.
  const acknowledged = sellSource === "tier" && fin(tierCost)
    ? {
        sell: tierTotal,
        cost: tierCost,
        marginAmount: tierTotal - tierCost,
        marginPct: tierTotal > 0 ? ((tierTotal - tierCost) / tierTotal) * 100 : null,
        differs: cost === null || Math.abs(tierCost - cost) > 0.005,
      }
    : null;

  return {
    cost: { value: cost, source: costSource },
    sell: { value: sell, source: sellSource, label: sellLabel },
    margin: { amount: marginAmount, pct: marginPct, basis: marginBasis },
    acknowledged,
    projectLinked,
    pricingUnavailable: pricingUnavailable === true,
  };
}

// ─── Itemized takeoff ────────────────────────────────────────────────────────
//
// Itemized = per-component rows grouped by section, each carrying the
// quantity basis and its own amount. Rows a held component leaves behind are
// flagged `held` (acknowledged snapshot shown) and amountless held rows keep
// `amount: null` → the UI renders "Not saved", never $0.
//
// Data slices are passed in so the module stays import-free; the component
// supplies calc.* (items/walls/poles/caps/equipment/delivery/pricing flags)
// and project-derived rows (cabinets, landscape) when wired.

export function buildFoundationTakeoff({
  totals = {},
  items = null,
  itemPricing = null,
  walls = null,
  wallPricing = null,
  poles = null,
  polePricing = null,
  wallCaps = null,
  equipment = null,
  equipmentPricing = null,
  delivery = null,
  cabinets = null,
  cabinetRows = null,
  landscapeLines = null,
  landscapePricing = null,
} = {}) {
  const groups = [];
  const addGroup = (key, label, rows) => {
    if (rows.length) groups.push({ key, label, rows });
  };

  // ── Foundations: one row per item + the delivery order row ──
  const foundationRows = [];
  arr(items).forEach((item, index) => {
    const held = arr(itemPricing)[index]?.available === false;
    const typeLabel = FOUNDATION_TYPE_LABEL[item?.foundation_type] || "foundation";
    const qty = joinQty([
      fmtQty(numOrNull(item?.concrete_volume_cy), "CY"),
      numOrNull(item?.rebar_feet) > 0 ? fmtQty(numOrNull(item.rebar_feet), "LF rebar", 1) : null,
      numOrNull(item?.forming_qty) > 0 ? fmtQty(numOrNull(item.forming_qty), "forming", 1) : null,
      numOrNull(item?.excavation_volume_cy) > 0 ? fmtQty(numOrNull(item.excavation_volume_cy), "CY dug") : null,
    ]);
    foundationRows.push({
      key: `item-${index}`,
      label: `Item ${index + 1} — ${typeLabel} ×${numOrNull(item?.quantity) ?? 1}`,
      qty,
      amount: fin(item?.item_total_cost) ? item.item_total_cost : null,
      held,
    });
  });
  const deliveryRows = (() => {
    // Live delivery from calc when wired; otherwise the totals snapshot fields.
    const src = isRecord(delivery) ? delivery : null;
    const yards = src ? numOrNull(src.roundedYards) : numOrNull(totals?.concrete_delivered_yards);
    const trucks = src ? arr(src.trucksList).length : arr(totals?.concrete_trucks).length;
    const amount = src ? numOrNull(src.concreteTotal) : numOrNull(totals?.concrete_delivery_cost);
    const held = src?.pricingUnavailable === true;
    if (yards === null && !trucks && amount === null) return [];
    return [{
      key: "delivery",
      label: "Concrete delivery",
      qty: joinQty([
        yards !== null ? fmtQty(yards, "yd", 1) : null,
        trucks > 0 ? `${trucks} truck${trucks === 1 ? "" : "s"}` : null,
        fin(numOrNull(src?.additionalStopsCost ?? totals?.additional_stops_cost)) && numOrNull(src?.additionalStopsCost ?? totals?.additional_stops_cost) > 0
          ? "+ extra stops" : null,
      ]),
      amount,
      held,
    }];
  })();
  addGroup("foundations", "Foundations", [...foundationRows, ...deliveryRows]);

  // ── Masonry walls: one row per wall, material + labor + internal fill ──
  addGroup("masonry", "Masonry walls", arr(walls).map((wall, index) => {
    const held = arr(wallPricing)[index]?.available === false;
    const cc = isRecord(wall?.calculatedCosts) ? wall.calculatedCosts : {};
    const matUnit = cc.materialQuantityUnit === "cy" ? "CY" : "units";
    const linearFt = numOrNull(cc.totalLinearInches);
    const qty = joinQty([
      numOrNull(cc.totalBricks) !== null ? fmtQty(numOrNull(cc.totalBricks), matUnit, 0) : null,
      linearFt !== null ? fmtQty(linearFt / 12, "LF outline", 1) : null,
      numOrNull(cc.internalTotalBricks) > 0
        ? `+${fmtQty(numOrNull(cc.internalTotalBricks), cc.internalMaterialQuantityUnit === "cy" ? "CY" : "units", 0)} internal`
        : null,
    ]);
    return {
      key: `wall-${index}`,
      label: wall?.name || `Wall ${index + 1}`,
      qty,
      amount: fin(cc.totalCost) ? cc.totalCost : null,
      held,
    };
  }));

  // ── Poles: billed required length + stock count (+ painting flag) ──
  addGroup("poles", "Poles", arr(poles).map((pole, index) => {
    const held = arr(polePricing)[index]?.available === false;
    const billedInches = numOrNull(pole?.required_length_inches)
      ?? (numOrNull(pole?.height_inches) !== null && numOrNull(pole?.embedment_inches ?? pole?.y_offset_inches) !== null
        ? numOrNull(pole.height_inches) + numOrNull(pole.embedment_inches ?? pole?.y_offset_inches)
        : null);
    const qty = joinQty([
      billedInches !== null ? fmtQty(billedInches / 12, "LF billed", 1) : null,
      numOrNull(pole?.stock_pieces) > 0 ? `${numOrNull(pole.stock_pieces)} stock pc${numOrNull(pole.stock_pieces) === 1 ? "" : "s"}` : null,
      numOrNull(pole?.pole_painting_cost) > 0 ? "+ painting" : null,
    ]);
    return {
      key: `pole-${index}`,
      label: pole?.pole_name || `Pole ${index + 1}`,
      qty,
      amount: fin(pole?.total_cost) ? pole.total_cost : null,
      held,
    };
  }));

  // ── Wall caps: per-piece rows when calc is wired; per-material rollup
  //    from the totals snapshot otherwise ──
  const capRows = (() => {
    if (Array.isArray(wallCaps) && wallCaps.length) {
      return wallCaps.map((cap, index) => {
        const cut = numOrNull(cap?.length_inches ?? cap?.cut_length_inches);
        return {
          key: `cap-${index}`,
          label: cap?.cap_name || `Cap ${index + 1}`,
          qty: joinQty([cut !== null ? fmtQty(cut, "in cut", 1) : null]),
          amount: fin(cap?.cost) ? cap.cost : null,
          held: !fin(cap?.cost),
        };
      });
    }
    return arr(totals?.wall_caps_by_material).map((g, index) => ({
      key: `capmat-${index}`,
      label: g?.name || `Wall cap material ${index + 1}`,
      qty: numOrNull(g?.qty) !== null ? `${numOrNull(g.qty)} pcs` : null,
      amount: fin(g?.cost) ? g.cost : null,
      held: !fin(g?.cost),
    }));
  })();
  addGroup("wall_caps", "Wall caps", capRows);

  // ── Equipment rentals: period + duration + delivery flag ──
  addGroup("equipment", "Equipment", arr(equipment).map((entry, index) => {
    const held = arr(equipmentPricing)[index]?.available === false;
    const duration = numOrNull(entry?.custom_qty ?? entry?.rental_duration) ?? 1;
    const period = entry?.rental_period || "day";
    const qty = joinQty([
      fmtQty(duration, period, 1),
      entry?.include_delivery ? "+ delivery" : null,
    ]);
    return {
      key: `equip-${index}`,
      label: `Equipment ${index + 1}`,
      qty,
      amount: fin(entry?.equipment_cost) ? entry.equipment_cost : null,
      held,
    };
  }));

  // ── Signage cabinets (page-level extras; priced rows passed in) ──
  addGroup("cabinets", "Signage cabinets", arr(cabinetRows).map((row, index) => {
    const cabinet = arr(cabinets)[index] || {};
    const quantity = cabinet.quantity === undefined || cabinet.quantity === null || cabinet.quantity === ""
      ? 1 : numOrNull(cabinet.quantity);
    return {
      key: `cabinet-${index}`,
      label: cabinet.description || `Cabinet ${index + 1}`,
      qty: quantity !== null ? `${numOrNull(quantity)} pcs` : null,
      amount: fin(row?.cost) ? row.cost : null,
      held: row?.available === false,
    };
  }));

  // ── Site landscape: one row per recorded material ──
  addGroup("landscape", "Site landscape", arr(landscapeLines).map((line, index) => ({
    key: `land-${index}`,
    label: line?.label || `Material ${index + 1}`,
    qty: fin(line?.sqft) ? fmtQty(line.sqft, "sq ft") : (numOrNull(line?.cells) !== null ? `${numOrNull(line.cells)} cells` : null),
    amount: fin(line?.cost) ? line.cost : null,
    held: landscapePricing?.available === false || !fin(line?.cost),
  })));

  const rowCount = groups.reduce((s, g) => s + g.rows.length, 0);
  return { groups, rowCount };
}

// ─── Missing-input checklist ─────────────────────────────────────────────────
//
// Enumerates the held/unavailable inputs the surface already knows about.
// Blocking channels (design inputs, catalog & settings) are the same lists
// the page's pricingBlocked gate reads; advisory channels (placement,
// construction checks) never block; the held-amounts channel enumerates
// partition buckets whose amount is currently unavailable — it catches held
// components even when the upstream issue list misses them (e.g. wall-cap
// holds, whose issues do not reach the calc channels).
//
// `channelsKnown` distinguishes "issues were checked and none exist" from
// "no issue channel was wired to this panel" — the complete/empty state must
// only be claimed when the channels were actually consulted.

export function buildFoundationInputChecklist({
  totals = {},
  pricingUnavailable = false,
  calc = null,
  issues = null,
  assemblyIssues = null,
} = {}) {
  const src = isRecord(issues) ? issues : isRecord(calc) ? calc : {};
  const channelsKnown = isRecord(issues) || isRecord(calc);
  const catalogIssues = arr(src.catalogIssues);
  const inputIssues = arr(src.inputIssues);
  const constructionWarnings = arr(src.constructionWarnings);
  const placements = arr(assemblyIssues);

  const seen = new Set();
  const items = (list) => arr(list).filter((issue) => {
    const key = `${issue?.code ?? ""}|${issue?.kind ?? ""}|${issue?.index ?? ""}|${issue?.componentId ?? ""}|${issue?.field ?? ""}|${issue?.message ?? issue ?? ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((issue, i) => ({
    key: `${issue?.code ?? "issue"}-${issue?.kind ?? ""}-${issue?.index ?? i}-${issue?.field ?? ""}-${i}`,
    message: String(issue?.message ?? issue),
    code: issue?.code ?? null,
    field: issue?.field ?? null,
  }));

  const heldItems = [];
  for (const [field, label] of FOUNDATION_STICKY_PARTITION_FIELDS) {
    if (!fin(totals?.[field])) {
      heldItems.push({
        key: `held-${field}`,
        message: `${label} — amount unavailable (saved amount shown where recorded)`,
        code: "held_amount",
        field,
      });
    }
  }
  if (isRecord(calc?.delivery) && calc.delivery.pricingUnavailable === true) {
    heldItems.push({
      key: "held-delivery",
      message: "Concrete delivery — held at the saved order snapshot",
      code: "held_amount",
      field: "delivery",
    });
  }
  // Catch-all: pricing paused but no enumerated reason (defensive — the
  // blocked gate should always have a reason, but never render an empty
  // checklist under an unavailable banner).
  if (pricingUnavailable === true && inputIssues.length === 0 && catalogIssues.length === 0 && heldItems.length === 0) {
    heldItems.push({
      key: "held-pricing",
      message: "Pricing is paused — review highlighted inputs and catalog selections",
      code: "pricing_paused",
      field: null,
    });
  }

  const groups = [
    { key: "inputs", label: "Design inputs", severity: "blocking", items: items(inputIssues) },
    { key: "catalog", label: "Catalog & settings", severity: "blocking", items: items(catalogIssues) },
    { key: "assembly", label: "Placement", severity: "advisory", items: items(placements) },
    { key: "checks", label: "Construction checks", severity: "advisory", items: items(constructionWarnings) },
    { key: "held", label: "Held amounts", severity: "held", items: heldItems },
  ].filter((g) => g.items.length > 0);

  const blockingCount = groups.filter((g) => g.severity === "blocking").reduce((s, g) => s + g.items.length, 0);
  const advisoryCount = groups.filter((g) => g.severity === "advisory").reduce((s, g) => s + g.items.length, 0);
  const heldCount = heldItems.length;
  const totalCount = groups.reduce((s, g) => s + g.items.length, 0);

  return {
    groups,
    blockingCount,
    advisoryCount,
    heldCount,
    totalCount,
    channelsKnown,
    // "Complete" is only claimed when the issue channels were actually
    // consulted and nothing is outstanding — never assumed on an unwired panel.
    complete: channelsKnown && totalCount === 0,
  };
}

import { useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Undo2, Trash2, Square } from "lucide-react";
import { foundationWallOutlineBasis, foundationWallRectangle, foundationWallSegments } from "./wallCalculator";

// Wall footprint in inches. Shape (matches SignEstimate Pro):
//   { points: [{x, z}], closed: bool, segments: [{ length }] }
const PX_PER_IN = 1.4; // canvas scale
const SNAP = 2; // snap to 2"

export function buildSegments(points, closed) {
  return foundationWallSegments(points, closed);
}

const shapeRecord = (current) =>
  current && typeof current === "object" && !Array.isArray(current) ? current : {};

const emitShape = (current, points, closed) => {
  const segments = foundationWallSegments(points, closed);
  if (!segments) return null;
  return { ...shapeRecord(current), points, closed, segments };
};

export default function WallShapeEditor({ shape, onChange }) {
  const basis = foundationWallOutlineBasis(shape);
  const points = basis.points;
  const closed = basis.closed;
  const [rect, setRect] = useState({ l: 96, w: 48 });
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const gridId = `wallGrid-${uid}`;
  const rectLId = `rectL-${uid}`;
  const rectWId = `rectW-${uid}`;
  const rectErrId = `rect-err-${uid}`;

  const W = 520;
  const H = 300;
  const toPx = (p) => ({ x: p.x * PX_PER_IN + 20, y: p.z * PX_PER_IN + 20 });

  const addPoint = (e) => {
    if (closed) return;
    const box = e.currentTarget.getBoundingClientRect();
    const sx = (e.clientX - box.left) * (W / box.width);
    const sy = (e.clientY - box.top) * (H / box.height);
    const x = Math.max(0, Math.round((sx - 20) / PX_PER_IN / SNAP) * SNAP);
    const z = Math.max(0, Math.round((sy - 20) / PX_PER_IN / SNAP) * SNAP);
    if (!Number.isFinite(x) || !Number.isFinite(z)) return;
    const last = points[points.length - 1];
    if (last && last.x === x && last.z === z) return;
    const next = emitShape(shape, [...points, { x, z }], false);
    if (next) onChange(next);
  };

  const rectShape = foundationWallRectangle(rect.l, rect.w);
  const rectLBad = foundationWallRectangle(rect.l, 1) === null;
  const rectWBad = foundationWallRectangle(1, rect.w) === null;
  const setRectangle = () => {
    if (!rectShape) return;
    onChange({ ...shapeRecord(shape), ...rectShape });
  };

  const segments = Array.isArray(shape?.segments) ? shape.segments : [];
  const hasSegmentLengths = segments.length > 0;
  const legacyOnly = !basis.hasRecordedPoints && hasSegmentLengths;
  const malformedPoints = basis.hasRecordedPoints && !points.length;
  const clearable = points.length > 0 || hasSegmentLengths || shape?.points != null || shape?.segments != null;
  const perimeter = basis.perimeterInches;
  const emit = (pointsNext, closedNext) => {
    const next = emitShape(shape, pointsNext, closedNext);
    if (next) onChange(next);
  };

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-end gap-2">
        <label className="text-xs text-gray-500">
          Rect L (in)
          <Input
            type="number"
            step="any"
            className="w-24"
            value={rect.l}
            id={rectLId}
            aria-invalid={rectLBad || undefined}
            aria-describedby={rectLBad ? rectErrId : undefined}
            onChange={(e) => setRect({ ...rect, l: e.target.value })}
          />
        </label>
        <label className="text-xs text-gray-500">
          Rect W (in)
          <Input
            type="number"
            step="any"
            className="w-24"
            value={rect.w}
            id={rectWId}
            aria-invalid={rectWBad || undefined}
            aria-describedby={rectWBad ? rectErrId : undefined}
            onChange={(e) => setRect({ ...rect, w: e.target.value })}
          />
        </label>
        <Button variant="outline" size="sm" onClick={setRectangle} disabled={!rectShape}
          aria-describedby={!rectShape ? rectErrId : undefined}>
          <Square className="w-4 h-4" aria-hidden="true" /> Use rectangle
        </Button>
        {!rectShape && (
          <span role="status" id={rectErrId} className="text-xs text-amber-600">
            Rectangle dimensions must be positive finite inches; current outline is unchanged.
          </span>
        )}
        <Button
          variant="outline"
          size="sm"
          disabled={points.length < 3 || closed}
          onClick={() => emit(points, true)}
        >
          Close outline
        </Button>
        <Button
          variant="ghost"
          size="sm"
          disabled={!points.length}
          onClick={() => emit(points.slice(0, -1), false)}
        >
          <Undo2 className="w-4 h-4" aria-hidden="true" /> Undo
        </Button>
        <Button
          variant="ghost"
          size="sm"
          disabled={!clearable}
          onClick={() => {
            if (!window.confirm("Clear the drawn outline?")) return;
            onChange({ ...shapeRecord(shape), points: [], closed: false, segments: [] });
          }}
        >
          <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" /> Clear
        </Button>
      </div>

      <svg
        width="100%"
        viewBox={`0 0 ${W} ${H}`}
        onClick={addPoint}
        className="rounded-lg border border-gray-200 bg-slate-50"
        style={{ cursor: closed ? "default" : "crosshair" }}
      >
        <defs>
          <pattern id={gridId} width={12 * PX_PER_IN} height={12 * PX_PER_IN} patternUnits="userSpaceOnUse">
            <path d={`M ${12 * PX_PER_IN} 0 L 0 0 0 ${12 * PX_PER_IN}`} fill="none" stroke="#e2e8f0" strokeWidth="1" />
          </pattern>
        </defs>
        <rect width={W} height={H} fill={`url(#${gridId})`} />

        {points.length > 1 && (
          <polyline
            points={[...points, ...(closed ? [points[0]] : [])].map((p) => {
              const q = toPx(p);
              return `${q.x},${q.y}`;
            }).join(" ")}
            fill={closed ? "rgba(248,113,113,0.12)" : "none"}
            stroke="#ef4444"
            strokeWidth="3"
          />
        )}

        {points.map((p, i) => {
          const q = toPx(p);
          return <circle key={i} cx={q.x} cy={q.y} r="5" fill="#fff" stroke="#ef4444" strokeWidth="2" />;
        })}

        {points.length === 0 && (
          <text x="20" y="28" fontSize="12" fill="#94a3b8">
            Click to place footprint corners, or enter a rectangle above.
          </text>
        )}
      </svg>

      <div className="text-xs text-gray-600">
        {hasSegmentLengths ? `${segments.length} segment${segments.length === 1 ? "" : "s"}` : "no segments"} · perimeter{" "}
        <span className="font-semibold text-gray-900">{perimeter === null ? "Unavailable" : `${Math.round(perimeter)}"`}</span>
        {closed ? " · closed" : points.length > 2 ? " · open (close it for an internal fill wall)" : ""}
      </div>
      {legacyOnly && (
        <div role="status" className="text-xs text-amber-600">
          Recorded segment lengths only — no drawable footprint. Draw or enter a rectangle to re-establish geometry.
        </div>
      )}
      {malformedPoints && (
        <div role="status" className="text-xs text-amber-600">
          Recorded footprint coordinates need repair before a preview can be drawn.
        </div>
      )}
    </div>
  );
}

import { calcProject } from "./foundationCalc";
import { createFoundationReinforcementDraft } from "./foundationReinforcementDraft";
import { createFoundationReinforcementProposal, acceptFoundationReinforcementProposal } from "./foundationReinforcementProposal";

const plain = value => value !== null && typeof value === "object" && !Array.isArray(value)
  && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const finite = value => typeof value === "number" && Number.isFinite(value);
const money = value => finite(value)
  ? `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "Unavailable";
const quantity = value => finite(value) ? value.toLocaleString("en-US", { maximumFractionDigits: 2 }) : "Not recorded";
const emptyAcknowledgments = () => ({ preliminary: false, warningCodes: [] });
const sameAnchors = (before, after) => before && before.project === after.project
  && before.savedProject === after.savedProject && before.inventory === after.inventory && before.settings === after.settings
  && before.contextKey === JSON.stringify(after.context);
const anchors = input => ({ ...input, contextKey: JSON.stringify(input.context) });

// Mirrors the page's own sectionTotal exactly: grand_total plus the held-aware
// cabinet and landscape totals. When recorded extras cannot be repriced the
// calc keeps the acknowledged project totals (or null) — never a silently
// guessed amount — so the proposal's before/after section rows report the same
// number the toolbar and estimate handoff see.
function section(input, project) {
  const calculation = calcProject(project, input.inventory, input.settings, { savedProject: input.savedProject });
  const base = calculation.totals.grand_total;
  const cabinetCost = calculation.totals.total_signage_cabinet_cost;
  const landscapeCost = calculation.totals.total_landscape_cost;
  const total = finite(base) && finite(cabinetCost) && finite(landscapeCost) ? base + cabinetCost + landscapeCost : null;
  return { calculation, total };
}

function proposalView(proposal, input, componentId) {
  const issues = [...proposal.issues], comparisons = proposal.comparisons;
  const proposedCost = proposal.projection?.itemCost;
  let before, after, sectionDelta = null;
  if (proposal.prepared && proposedCost) {
    try {
      const prepared = proposal.prepared;
      const project = { ...input.project, items: input.project.items.map(item => item.component_id === componentId ? {
        ...item, reinforcement_calculation_version: 2, reinforcement_design: prepared.design,
        reinforcement_material: prepared.material, custom_rebar_qty: prepared.overrides.quantity_ft,
        custom_rebar_cost_per_ft: prepared.overrides.cost_per_ft,
      } : item) };
      before = section(input, input.project);
      after = section(input, project);
      if (finite(before.total) && finite(after.total)) sectionDelta = after.total - before.total;
      if (after.calculation.catalogIssues.length || after.calculation.inputIssues.length) sectionDelta = null;
    } catch {
      sectionDelta = null;
    }
  }
  if (!finite(sectionDelta)) issues.push({
    code: "reinforcement_section_delta_unavailable", severity: "error",
    message: "The full Concrete section delta is unavailable. Resolve other design or catalog issues and refresh before accepting.",
  });
  const currentItem = before?.calculation.items.find(item => item.component_id === componentId);
  const currentProvenance = comparisons?.currentProvenance || "Current amount unavailable";
  const sectionProvenance = before?.calculation.catalogIssues.length || before?.calculation.inputIssues.length
    ? "Current section with acknowledged fallback amounts where unavailable" : "Current full Concrete section calculation";
  const row = (label, value, provenance) => ({ label, value: money(value), provenance });
  return {
    id: proposal.id, canAccept: proposal.canAccept && finite(sectionDelta), stale: false,
    warningCodes: [...(proposal.warningCodes || [])], issues,
    quantities: [
      { label: "Physical steel (ft)", before: quantity(currentItem?.rebar_geometry_feet), after: quantity(proposedCost?.rebar_geometry_feet) },
      { label: "Priced steel (ft)", before: quantity(currentItem?.rebar_feet), after: quantity(proposedCost?.rebar_feet) },
      { label: "Reinforcement labor (hr)", before: quantity(currentItem?.rebar_labor_hours), after: quantity(proposedCost?.rebar_labor_hours) },
    ],
    costs: [
      row("Current steel", comparisons?.steel.before, currentProvenance),
      row("Proposed steel", comparisons?.steel.proposed, "Fresh preliminary internal steel cost"),
      row("Steel delta", comparisons?.steel.delta, "Proposed minus current"),
      row("Current foundation", comparisons?.item.before, currentProvenance),
      row("Proposed foundation", comparisons?.item.proposed, "Fresh full foundation cost"),
      row("Foundation delta", comparisons?.item.delta, "Proposed minus current"),
      row("Current section", before?.total, sectionProvenance),
      row("Proposed section", after?.total, "Full Concrete section including signage and landscape"),
      row("Section delta", sectionDelta, "Proposed minus current; not a customer selling price"),
      row("Saved steel", comparisons?.savedSteel, "Acknowledged saved source"),
      row("Saved foundation", comparisons?.savedItem, "Acknowledged saved source"),
    ],
  };
}

// Parent owns the raw draft, acknowledged source, history and saves. This session
// owns only disposable previews/acknowledgments; acceptance is one parent commit.
export function createFoundationReinforcementEditorSession({ getCurrent, commit, createId, now, onChange = () => {} }) {
  const entries = new Map();
  let scope;
  const current = () => {
    const input = getCurrent();
    const nextScope = JSON.stringify([input.context?.ownerId, input.context?.sourceId,
      input.context?.estimateId, input.context?.generation]);
    if (scope !== nextScope) { entries.clear(); scope = nextScope; }
    return input;
  };
  const entryFor = id => {
    if (!entries.has(id)) entries.set(id, { acknowledgments: emptyAcknowledgments(), proposal: null, view: null, activeId: null, error: "" });
    return entries.get(id);
  };
  const findItem = (input, id) => {
    const matches = input.project?.items?.filter(item => item.component_id === id) || [];
    return matches.length === 1 ? matches[0] : null;
  };
  const allowed = (input, id) => input.context?.loaded === true && !input.blocked && Boolean(findItem(input, id));
  const report = (entry, message) => { entry.error = message; onChange(); return false; };
  const reset = entry => Object.assign(entry, { acknowledgments: emptyAcknowledgments(), proposal: null, view: null, activeId: null, error: "" });
  const edit = (id, update) => {
    const input = current(), entry = entryFor(id);
    if (!allowed(input, id)) return report(entry, "The editor context is unavailable or busy; no proposal was changed.");
    const item = findItem(input, id);
    const nextItem = update(item);
    const ok = commit(previous => ({ items: previous.items.map(record => record.component_id === id ? nextItem : record) }));
    if (ok !== true) return report(entry, "The proposal edit could not be committed in the current editor.");
    reset(entry); onChange(); return true;
  };
  return {
    read(id) {
      const input = current(), entry = entryFor(id), item = findItem(input, id);
      return {
        draft: item?.reinforcement_proposal ?? null,
        preview: entry.view ? { ...entry.view, stale: entry.activeId !== entry.proposal?.id || !sameAnchors(entry.anchors, input) } : null,
        acknowledgments: structuredClone(entry.acknowledgments), error: entry.error,
        disabled: !allowed(input, id),
      };
    },
    start(id) {
      return edit(id, item => ({ ...item, reinforcement_proposal: createFoundationReinforcementDraft(item) }));
    },
    changeDraft(id, draft) {
      if (!plain(draft)) return false;
      return edit(id, item => ({ ...item, reinforcement_proposal: structuredClone(draft) }));
    },
    discard(id) {
      return edit(id, item => { const next = { ...item }; delete next.reinforcement_proposal; return next; });
    },
    acknowledge(id, value) {
      const input = current(), entry = entryFor(id);
      if (!allowed(input, id) || !plain(value) || typeof value.preliminary !== "boolean"
        || !Array.isArray(value.warningCodes) || value.warningCodes.some(code => typeof code !== "string" || !code.trim())) return false;
      entry.acknowledgments = { preliminary: value.preliminary, warningCodes: [...new Set(value.warningCodes)] };
      entry.activeId = null; entry.error = ""; onChange(); return true;
    },
    preview(id) {
      const input = current(), entry = entryFor(id), item = findItem(input, id);
      if (!allowed(input, id) || !item?.reinforcement_proposal) return report(entry, "Start a proposal in the current editor before previewing.");
      try {
        const proposal = createFoundationReinforcementProposal({
          ...input, rawDraft: item.reinforcement_proposal, componentId: id, proposalId: createId(),
          acknowledgments: entry.acknowledgments,
        });
        entry.proposal = proposal; entry.view = proposalView(proposal, input, id);
        entry.activeId = proposal.id; entry.anchors = anchors(input); entry.error = "";
        onChange(); return true;
      } catch (error) { entry.activeId = null; return report(entry, error.message || "The proposal could not be calculated."); }
    },
    accept(id, requestedId) {
      const input = current(), entry = entryFor(id), item = findItem(input, id);
      if (!allowed(input, id) || !entry.view?.canAccept || !entry.activeId || requestedId !== entry.activeId
        || !sameAnchors(entry.anchors, input)) return report(entry, "Refresh and review the current proposal before accepting.");
      const activeProposalId = entry.activeId;
      entry.activeId = null;
      const result = acceptFoundationReinforcementProposal({
        ...input, rawDraft: item.reinforcement_proposal, acknowledgments: entry.acknowledgments,
        proposal: entry.proposal, requestedId, activeProposalId, acceptedAt: now(),
      });
      if (!result.ok) return report(entry, result.message);
      if (commit(() => result.project) !== true) return report(entry, "Acceptance could not be committed; refresh the proposal.");
      reset(entry); onChange(); return true;
    },
  };
}

import { useState } from "react";
import ReinforcementDraftField from "./ReinforcementDraftField";

const PAGE = 20;
export const uuidOk = () => typeof globalThis.crypto?.randomUUID === "function";
export const newRowId = (prefix) => `${prefix}_${globalThis.crypto.randomUUID()}`;

const isValidRow = (r) => r && typeof r === "object" && !Array.isArray(r);
const strOrInvalid = (v) => (v === null || v === undefined || v === "" ? "" : typeof v === "string" ? v : "__invalid__");

// Generic raw-draft row list: paginated at 20, never truncates stored data.
export default function ReinforcementDraftList({ title, listKey, rows, fields, onReplaceList, onAdd, onDelete, onFieldChange, disabled, addLabel = "Add", maxRows }) {
  const [page, setPage] = useState(0);

  if (rows !== undefined && !Array.isArray(rows)) {
    return (
      <div data-list={listKey} className="rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[12px] text-amber-800">
        {title} list malformed.{" "}
        <button type="button" disabled={disabled} onClick={onReplaceList} className="underline disabled:text-gray-400">Replace List</button>
      </div>
    );
  }

  const safe = Array.isArray(rows) ? rows : [];
  const pages = Math.max(1, Math.ceil(safe.length / PAGE));
  const pageIdx = Math.min(page, pages - 1);
  const shown = safe.slice(pageIdx * PAGE, pageIdx * PAGE + PAGE);
  const atCap = maxRows != null && safe.length >= maxRows;
  const canAdd = !disabled && !atCap && uuidOk();

  return (
    <div data-list={listKey} className="rounded-sm border border-gray-200 min-w-0 max-w-full">
      <div className="flex items-center justify-between gap-2 border-b border-gray-100 px-2 py-1">
        <p className="text-[12px] font-semibold text-gray-700 break-words min-w-0">{title}</p>
        <button type="button" data-add={listKey} disabled={!canAdd} onClick={onAdd} className="shrink-0 text-[12px] text-amber-700 hover:underline disabled:text-gray-300">
          {addLabel}
        </button>
      </div>
      {!uuidOk() && <p className="px-2 py-1 text-[11px] text-amber-700">Secure row IDs unavailable in this browser; rows cannot be added.</p>}
      {atCap && <p className="px-2 py-1 text-[11px] text-gray-500">Row limit reached ({maxRows}).</p>}
      <div className="divide-y divide-gray-50">
        {shown.map((row, i) => {
          const idx = pageIdx * PAGE + i;
          const valid = isValidRow(row);
          const idStr = valid && typeof row.id === "string" ? row.id : null;
          if (!valid) {
            return (
              <div data-row={`${listKey}:${idx}`} key={`bad-${idx}`} className="flex flex-wrap items-center gap-2 px-2 py-1.5 text-[12px] text-red-700">
                <span>Malformed row - delete to repair.</span>
                <button type="button" data-del={`${listKey}:${idx}`} disabled={disabled} onClick={() => onDelete(idx)} className="text-[12px] text-red-600 hover:underline disabled:text-gray-300">Delete</button>
              </div>
            );
          }
          return (
            <div data-row={`${listKey}:${idx}`} data-row-id={idStr ?? undefined} key={`${idStr ?? "invalid"}:${idx}`} className="flex flex-wrap items-end gap-2 px-2 py-1.5">
              {idStr && <span className="w-full max-w-full break-words text-[10px] text-gray-400">{idStr}</span>}
              {!idStr && <span className="w-full max-w-full break-words text-[10px] text-red-600">Invalid or missing row id</span>}
              {fields.map(({ key, label, options }) =>
                options ? (
                  <label key={key} className="block min-w-0">
                    <span className="text-[12px] text-gray-600">{label}</span>
                    <select
                      value={strOrInvalid(row[key])}
                      disabled={disabled}
                      onChange={(e) => onFieldChange(idx, key, e.target.value)}
                      className="mt-0.5 block max-w-full rounded-sm border border-gray-300 px-1.5 py-1 text-[13px] disabled:bg-gray-50"
                    >
                      {options.map((o, oi) => <option key={`${o.id ?? o}-${oi}`} value={o.id ?? o}>{o.label ?? o}</option>)}
                      {row[key] !== undefined && row[key] !== null && typeof row[key] !== "string" && (
                        <option value="__invalid__" disabled>Invalid value</option>
                      )}
                      {typeof row[key] === "string" && row[key] !== "" && !options.some(o => (o.id ?? o) === row[key]) && (
                        <option value={row[key]} disabled>Missing: {row[key]}</option>
                      )}
                    </select>
                  </label>
                ) : (
                  <ReinforcementDraftField key={key} label={label} value={row[key]} disabled={disabled} onChange={(v) => onFieldChange(idx, key, v)} />
                )
              )}
              <button type="button" data-del={`${listKey}:${idx}`} disabled={disabled} onClick={() => onDelete(idx)} className="text-[12px] text-red-600 hover:underline disabled:text-gray-300">
                Delete
              </button>
            </div>
          );
        })}
        {!shown.length && <p className="px-2 py-2 text-[12px] text-gray-400">None.</p>}
      </div>
      {pages > 1 && (
        <div className="flex items-center justify-between border-t border-gray-100 px-2 py-1 text-[12px] text-gray-500">
          <button type="button" data-page="prev" disabled={disabled || pageIdx === 0} onClick={() => setPage(pageIdx - 1)} className="disabled:text-gray-300">Prev</button>
          <span>Page {pageIdx + 1} / {pages}</span>
          <button type="button" data-page="next" disabled={disabled || pageIdx >= pages - 1} onClick={() => setPage(pageIdx + 1)} className="disabled:text-gray-300">Next</button>
        </div>
      )}
    </div>
  );
}

// Raw controlled input for draft numeric fields - preserves exact text, never parses or clamps.
export default function ReinforcementDraftField({ label, value, onChange, disabled, inputMode = "decimal", maxLength, suffix, placeholder, rawInvalid = false }) {
  const invalid = rawInvalid || (value != null && !["string", "number"].includes(typeof value))
    || (typeof value === "number" && !Number.isFinite(value));
  return (
    <label className="block min-w-0">
      <span className="text-[12px] text-gray-600">{label}</span>
      <span className="mt-0.5 flex items-center gap-1">
        <input
          type="text"
          aria-label={label}
          inputMode={inputMode}
          value={invalid ? "" : (value ?? "")}
          maxLength={maxLength}
          placeholder={placeholder}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
          className="w-full rounded-sm border border-gray-300 px-2 py-1 text-[13px] disabled:bg-gray-50 disabled:text-gray-400"
        />
        {invalid && <span className="text-[10px] text-red-600">Invalid</span>}
        {suffix && <span className="text-[12px] text-gray-500">{suffix}</span>}
      </span>
    </label>
  );
}

// O-104 (CMP-I03) + O-105 (CMP-I04) — pure write-shaping for the
// FoundationProject `design_basis` and `site_hazard` blocks.
//
// No React, no entity access: given the current block and an authored field
// patch, return the next block with provenance stamped — or a rejection. The
// FoundationDesignBasisPanel writes ONLY through these functions so a project
// basis is never minted, defaulted, or silently changed:
//
//   * Nothing is auto-filled. Absent stays absent; "" clears to absent
//     (explicit-empty vs authored), except latitude/longitude which the
//     schema declares nullable and which clear to an explicit null.
//   * An authored write stamps provenance — basis_source / entry_method
//     'manual' unless an official-report transcription is explicitly
//     selected this write; 'api' is a reserved enum value this writer can
//     never produce.
//   * basis_captured_at records the FIRST capture and is never rewritten;
//     basis_updated_at / input_timestamp move on every authored change, so a
//     basis never changes without a recorded when.
//   * A post-capture change to code_edition preserves the superseded value
//     in code_edition_prior — the trail that keeps an edition switch
//     visible instead of silent. Callers should commit edition changes at
//     whole-value granularity (blur/enter), not per keystroke, so the
//     prior is the true superseded edition.
//   * basis_locked gates all basis edits: writes touching content (or
//     unlocking itself) return { rejected: "basis_locked" } until the
//     caller passes confirmed:true — the recorded re-capture intent.

export const DESIGN_BASIS_VERSION = 1;
export const SITE_HAZARD_VERSION = 1;

export const BASIS_SOURCES = ["manual", "official_report", "api"];
export const ENTRY_METHODS = ["manual", "official_report", "api"];
// 'api' is reserved for a future automation writer — surfaces must not
// offer it; sanitize re-marks it 'manual' with an issue if one arrives.
export const WRITABLE_SOURCES = ["manual", "official_report"];

export const HAZARD_UNITS = ["imperial", "metric"];
export const RISK_CATEGORIES = ["I", "II", "III", "IV"];
export const EXPOSURE_CATEGORIES = ["B", "C", "D"];

const isRecord = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const isoNow = (now) =>
  typeof now === "string" && Number.isFinite(Date.parse(now)) ? now : new Date().toISOString();

// Content keys an authored write may replace/clear. A field present in
// `fields` replaces; "" / null removes the key (explicit-empty, never a
// fabricated value); absent keys keep current values.
const BASIS_TEXT_KEYS = ["code_edition", "jurisdiction", "basis_notes"];
const BASIS_CONTENT_KEYS = [...BASIS_TEXT_KEYS, "code_edition_prior", "basis_source"];

const mergeTextFields = (cur, fields, keys) => {
  const next = { ...cur };
  for (const k of keys) {
    if (!(k in fields)) continue;
    const v = fields[k];
    if (v === "" || v === undefined || v === null) delete next[k];
    else next[k] = v;
  }
  return next;
};

// A block "has content" when something substantive is recorded — the audit
// timestamps alone do not make an empty block a captured basis.
const hasBasisContent = (b) =>
  isRecord(b) &&
  [b.code_edition, b.jurisdiction, b.basis_notes].some(
    (v) => typeof v === "string" && v.trim() !== ""
  );

// Substance for provenance marking: any key outside the pure audit set.
// Without this, an all-empty write on an absent block would mint a
// source-only shell (a fabricated record of an entry that never happened).
const BASIS_AUDIT_KEYS = ["version", "basis_captured_at", "basis_updated_at", "basis_source"];
const HAZARD_AUDIT_KEYS = ["version", "input_timestamp", "entry_method"];
const hasSubstance = (o, auditKeys) =>
  isRecord(o) && Object.keys(o).some((k) => !auditKeys.includes(k));

const stableSans = (obj, omitKeys) => {
  const out = {};
  for (const k of Object.keys(obj || {}).sort()) {
    if (omitKeys.includes(k)) continue;
    out[k] = obj[k];
  }
  return JSON.stringify(out);
};

/**
 * Shape a design_basis write.
 * @param {object} current   currently stored block (may be absent/malformed)
 * @param {object} fields    authored patch (see BASIS_* key lists above)
 * @param {string} now       ISO timestamp to stamp (defaults to current time)
 * @param {boolean} confirmed  caller has collected the re-capture intent for
 *                           a locked basis
 * @returns {{ next: object|undefined, changed: boolean, issues: object[], rejected?: string }}
 *   `next === undefined` means the block should store null/absent
 *   (explicit clear), never a fabricated empty record.
 */
export function sanitizeDesignBasisWrite(current, fields = {}, { now, confirmed = false } = {}) {
  const cur = isRecord(current) ? current : {};
  const issues = [];
  const touchesContent = BASIS_CONTENT_KEYS.some((k) => k in fields);
  const touchesLock = "basis_locked" in fields;

  if (
    cur.basis_locked === true &&
    confirmed !== true &&
    (touchesContent || fields.basis_locked === false)
  ) {
    return {
      rejected: "basis_locked",
      next: cur,
      changed: false,
      issues: [
        {
          code: "basis_locked",
          field: "basis_locked",
          message:
            "Design basis is locked; confirm the re-capture before editing it.",
        },
      ],
    };
  }

  const next = mergeTextFields(cur, fields, BASIS_TEXT_KEYS);

  // Edition-change trail: a post-capture write that changes a recorded
  // edition preserves the superseded value — including clearing it (a
  // cleared edition is a change, not a silent absence). An explicit
  // code_edition_prior in the patch wins (future migration/restore paths).
  if (
    "code_edition" in fields &&
    typeof cur.code_edition === "string" &&
    cur.code_edition !== "" &&
    fields.code_edition !== cur.code_edition
  ) {
    next.code_edition_prior = cur.code_edition;
  } else if ("code_edition_prior" in fields) {
    if (fields.code_edition_prior === "" || fields.code_edition_prior === null)
      delete next.code_edition_prior;
    else next.code_edition_prior = fields.code_edition_prior;
  }

  // Provenance: an authored content edit re-marks the block 'manual' — a
  // hand-edited basis may not keep claiming a report/API provenance. An
  // explicit official_report in the patch is honored (transcription is an
  // authored choice); 'api' can never be produced here.
  if ("basis_source" in fields) {
    if (fields.basis_source === "api") {
      issues.push({
        code: "basis_source_reserved",
        field: "basis_source",
        message:
          "'api' provenance is reserved for a future automation writer; recorded 'manual'.",
      });
      next.basis_source = "manual";
    } else if (WRITABLE_SOURCES.includes(fields.basis_source)) {
      next.basis_source = fields.basis_source;
    } else {
      next.basis_source = "manual";
    }
  } else if (touchesContent && (hasSubstance(next, BASIS_AUDIT_KEYS) || hasSubstance(cur, BASIS_AUDIT_KEYS))) {
    // Only when the write actually has substance — either the resulting
    // block records something or a content-bearing block is being edited/
    // cleared (clearing is an authored change, never a silent absence).
    next.basis_source = "manual";
  }

  // Lock handling: the authored value is kept verbatim, but a block with no
  // basis content has nothing to lock — strip rather than record a phantom.
  if (touchesLock) {
    if (fields.basis_locked === true) next.basis_locked = true;
    else delete next.basis_locked;
  }
  if (next.basis_locked === true && !hasBasisContent(next) && !next.basis_captured_at) {
    delete next.basis_locked;
    if (fields.basis_locked === true) {
      issues.push({
        code: "basis_lock_nothing",
        field: "basis_locked",
        message: "Nothing is recorded to lock yet — capture edition or jurisdiction first.",
      });
    }
  }

  // Timestamps are audit provenance, not content — compare without them so
  // an identical re-write is a true no-op (no timestamp churn, no dirty
  // marking downstream).
  const CHURN_KEYS = ["basis_updated_at"];
  if (stableSans(next, CHURN_KEYS) === stableSans(cur, CHURN_KEYS)) {
    return { next: cur, changed: false, issues };
  }
  next.basis_captured_at =
    typeof cur.basis_captured_at === "string" && cur.basis_captured_at
      ? cur.basis_captured_at
      : isoNow(now);
  next.basis_updated_at = isoNow(now);
  next.version = DESIGN_BASIS_VERSION;

  const contentKeys = Object.keys(next).filter(
    (k) => !["version", "basis_captured_at", "basis_updated_at", "basis_source"].includes(k)
  );
  if (contentKeys.length === 0) {
    // Everything authored is gone — the block reduces to a pure audit shell
    // (captured/updated/source). Storing null is the honest representation
    // of "basis cleared"; the timestamps are dropped with it because the
    // clear itself is recorded by the editor's save trail, not a ghost block.
    return { next: undefined, changed: true, issues };
  }
  return { next, changed: true, issues };
}

/**
 * Shape a site_hazard write.
 * @returns same contract as sanitizeDesignBasisWrite — `next === undefined`
 * means store null/absent. Coordinate fields are the schema-declared
 * nullable numbers: "" / null in the patch record an explicit null, never a
 * fabricated 0. Out-of-range or non-finite coordinates are rejected from
 * the record (issue surfaced) while other authored fields still land.
 */
export function sanitizeSiteHazardWrite(current, fields = {}, { now } = {}) {
  const cur = isRecord(current) ? current : {};
  const issues = [];
  const next = { ...cur };

  for (const k of ["latitude", "longitude"]) {
    if (!(k in fields)) continue;
    const v = fields[k];
    if (v === null || v === "" || v === undefined) {
      // Explicitly recorded empty — schema-declared nullable number.
      next[k] = null;
      continue;
    }
    const n = Number(v);
    const [lo, hi] = k === "latitude" ? [-90, 90] : [-180, 180];
    if (!Number.isFinite(n) || n < lo || n > hi) {
      issues.push({
        code: `${k}_invalid`,
        field: k,
        message: `${k === "latitude" ? "Latitude" : "Longitude"} must be a number between ${lo} and ${hi}; the value was not recorded.`,
      });
      continue; // keep the previously recorded value, never the invalid one
    }
    next[k] = n;
  }

  const enumField = (key, allowed, label) => {
    if (!(key in fields)) return;
    const v = fields[key];
    if (v === "" || v === undefined || v === null) {
      delete next[key];
      return;
    }
    if (!allowed.includes(v)) {
      issues.push({
        code: `${key}_invalid`,
        field: key,
        message: `${label} must be one of ${allowed.join("/")}; the value was not recorded.`,
      });
      return;
    }
    next[key] = v;
  };
  enumField("units", HAZARD_UNITS, "Units");
  enumField("risk_category", RISK_CATEGORIES, "Risk category");
  enumField("exposure_category", EXPOSURE_CATEGORIES, "Exposure category");

  if ("exposure_assumption" in fields) {
    if (fields.exposure_assumption === "" || fields.exposure_assumption === null)
      delete next.exposure_assumption;
    else next.exposure_assumption = fields.exposure_assumption;
  }

  // Provenance mirrors design_basis: an authored write lands 'manual'
  // unless an official-report transcription is explicitly selected; 'api'
  // is reserved. A write carrying no content fields preserves the recorded
  // method (there is no entry to re-attribute).
  const touchesContent = [
    "latitude",
    "longitude",
    "units",
    "risk_category",
    "exposure_category",
    "exposure_assumption",
    "entry_method",
  ].some((k) => k in fields);
  if ("entry_method" in fields) {
    if (fields.entry_method === "api") {
      issues.push({
        code: "entry_method_reserved",
        field: "entry_method",
        message:
          "'api' provenance is reserved for a future automation writer; recorded 'manual'.",
      });
      next.entry_method = "manual";
    } else if (WRITABLE_SOURCES.includes(fields.entry_method)) {
      next.entry_method = fields.entry_method;
    } else {
      next.entry_method = "manual";
    }
  } else if (touchesContent && (hasSubstance(next, HAZARD_AUDIT_KEYS) || hasSubstance(cur, HAZARD_AUDIT_KEYS))) {
    next.entry_method = "manual";
  }

  const CHURN_KEYS = ["input_timestamp"];
  if (stableSans(next, CHURN_KEYS) === stableSans(cur, CHURN_KEYS)) {
    return { next: cur, changed: false, issues };
  }
  next.input_timestamp = isoNow(now);
  next.version = SITE_HAZARD_VERSION;

  const contentKeys = Object.keys(next).filter(
    (k) => !["version", "input_timestamp", "entry_method"].includes(k)
  );
  if (contentKeys.length === 0) {
    return { next: undefined, changed: true, issues };
  }
  return { next, changed: true, issues };
}

// O-094 (CMP-H03) — duplicate + mirror transforms over the foundation assembly
// arrays. Pure: the source project is never mutated, catalog ids and prices
// are never invented, and every transform returns a template-patch-shaped
// delta compatible with prepareFoundationTemplatePatch semantics — the page
// merges it as {...prev, ...patch}, so absent array keys preserve the
// target's rows and supplied arrays replace them wholesale.
//
// Geometry contract (foundationLayoutModel.js / foundationAssemblyModel.js —
// READ-only imports, the models that own these fields):
//   * items carry a TOP-LEFT plan corner in inches (x_inches/z_inches), an
//     unrotated footprint from foundationLayoutFootprint() (length_inches x
//     width_inches, or diameter x diameter for pillars), and a visual
//     rotation_degrees applied about the footprint center (CSS clockwise).
//   * poles carry a plan POINT in inches (x_inches/z_inches) — rendered as a
//     marker, no footprint, so they reflect/translate as points.
//   * walls carry shape.points [{x, z}] in plan inches. Segment lengths are
//     derived from consecutive points, so translation and reflection preserve
//     them exactly — no segment rewrite is needed or attempted.
//   * wall_caps and signage_cabinets carry NO plan coordinates — they are
//     positioned by component-id reference (wall + segment / pole +
//     foundation). They ride with their parents and are handled only through
//     reference remapping, never through geometry writes.
import { cloneFoundationComponents } from "./foundationAssemblyModel.js";
import {
  foundationLayoutFootprint,
  FOUNDATION_LAYOUT_WIDTH_INCHES,
  FOUNDATION_LAYOUT_DEPTH_INCHES,
} from "./foundationLayoutModel.js";

// Mirrors the template-model allowlist's assembly arrays — kept local so this
// module stays a pure geometry/assembly helper with no template dependency.
const ASSEMBLY_ARRAYS = ["items", "walls", "poles", "wall_caps", "signage_cabinets"];
const ID_RETRY_MAX = 8; // mirrors MAX_COLLISIONS in foundationAssemblyModel
const DEFAULT_OFFSET_INCHES = { x: 12, z: 12 };

const isRecord = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const fin = (v) => typeof v === "number" && Number.isFinite(v);
const isId = (v) => typeof v === "string" && v.length > 0;
const deepClone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
const cloneRow = (r) => {
  try {
    return deepClone(r);
  } catch {
    return isRecord(r) ? { ...r } : r;
  }
};
const normDeg = (v) => ((v % 360) + 360) % 360;
const rebuildIndex = (id, parents) => {
  if (!isId(id)) return undefined;
  const i = (parents || []).findIndex((p) => p?.component_id === id);
  return i >= 0 ? i : undefined;
};

// Every component id + component reference already live on the project — a
// fresh clone id must never collide with one of them (cloneFoundationComponents
// only dedupes against the subset it sees).
const collectUsedComponentIds = (project) => {
  const ids = new Set();
  const push = (v) => { if (isId(v)) ids.add(v); };
  for (const k of ASSEMBLY_ARRAYS) {
    for (const r of project?.[k] || []) {
      if (!isRecord(r)) continue;
      push(r.component_id);
      push(r.foundation_component_id);
      push(r.pole_component_id);
      push(r.wall_component_id);
      push(r.segment_component_id);
      push(r.source_item_component_id);
    }
  }
  for (const w of project?.walls || []) for (const s of w?.shape?.segments || []) push(s?.component_id);
  for (const p of project?.poles || []) for (const s of p?.signs || []) push(s?.component_id);
  return ids;
};

const collisionFreeId = (createId, used, kind) => {
  for (let i = 0; i < ID_RETRY_MAX; i += 1) {
    const id = createId(kind);
    if (isId(id) && !used.has(id)) { used.add(id); return id; }
  }
  throw new Error(`foundation duplicate/mirror: could not mint a collision-free ${kind} id`);
};

// Resolve which rows an operation acts on. component_ids absent => every row
// on the five arrays; supplied ids must each resolve to exactly one top-level
// row (fail closed on unknown ids). include_dependents pulls in rows anchored
// on a selected parent — a pole on a selected footing, a cap on a selected
// wall, a cabinet on a selected pole/footing — iterating to a fixpoint so a
// cabinet on a pole on a footing all travels together. Dependents added this
// way keep references outside the selection pointing at the ORIGINAL parents.
const selectRows = (project, componentIds, includeDependents) => {
  const selected = {};
  for (const k of ASSEMBLY_ARRAYS) selected[k] = new Set();
  if (componentIds !== undefined && componentIds !== null && !Array.isArray(componentIds)) {
    throw new Error("foundation duplicate/mirror: component_ids must be an array");
  }
  if (componentIds === undefined || componentIds === null) {
    for (const k of ASSEMBLY_ARRAYS) for (const r of project?.[k] || []) selected[k].add(r);
  } else {
    const lookup = new Map();
    for (const k of ASSEMBLY_ARRAYS) {
      for (const r of project?.[k] || []) {
        if (isId(r?.component_id) && !lookup.has(r.component_id)) lookup.set(r.component_id, { kind: k, row: r });
      }
    }
    const unmatched = componentIds.filter((id) => !lookup.has(id));
    if (unmatched.length) {
      throw new Error(`foundation duplicate/mirror: unknown component id(s): ${unmatched.join(", ")}`);
    }
    for (const id of componentIds) {
      const hit = lookup.get(id);
      selected[hit.kind].add(hit.row);
    }
  }
  if (includeDependents) {
    const itemIds = () => new Set([...selected.items].map((r) => r?.component_id).filter(isId));
    const wallIds = () => new Set([...selected.walls].map((r) => r?.component_id).filter(isId));
    const poleIds = () => new Set([...selected.poles].map((r) => r?.component_id).filter(isId));
    let grew = true;
    while (grew) {
      grew = false;
      const items = itemIds();
      for (const p of project?.poles || []) {
        if (!selected.poles.has(p) && items.has(p?.foundation_component_id)) { selected.poles.add(p); grew = true; }
      }
      const walls = wallIds();
      for (const c of project?.wall_caps || []) {
        if (!selected.wall_caps.has(c) && walls.has(c?.wall_component_id)) { selected.wall_caps.add(c); grew = true; }
      }
      const poles = poleIds();
      for (const c of project?.signage_cabinets || []) {
        if (selected.signage_cabinets.has(c)) continue;
        const pool = c?.mount === "pole" ? poles : items;
        const parent = c?.mount === "pole" ? c?.pole_component_id : c?.foundation_component_id;
        if (pool.has(parent)) { selected.signage_cabinets.add(c); grew = true; }
      }
    }
  }
  return selected;
};

const subsetOf = (project, selected) => {
  const out = {};
  for (const k of ASSEMBLY_ARRAYS) out[k] = (project?.[k] || []).filter((r) => selected[k].has(r));
  return out;
};

// Clone a subset/data record into fresh-id rows and append them after the
// project's existing rows. References inside the cloned set are remapped by
// cloneFoundationComponents; references pointing OUT of the set keep their
// original ids — a duplicated cap on a kept wall stays on that wall, a
// duplicated pole on a kept footing stays anchored. Dependent index fields
// (foundation_idx / wall_index / segment_index / pole_index / foundation_index)
// are rebuilt against the FINAL arrays, matching the rebuild in
// cloneFoundationComponents but over the merged row set.
export function appendClonedFoundationAssemblies(project, assemblyData, { createId, transformClone } = {}) {
  if (!isRecord(project)) throw new Error("foundation duplicate/mirror: project must be a record");
  if (!isRecord(assemblyData)) throw new Error("foundation duplicate/mirror: assembly data must be a record");
  if (typeof createId !== "function") throw new Error("foundation duplicate/mirror: createId(kind) factory is required");
  const used = collectUsedComponentIds(project);
  const guarded = (kind) => collisionFreeId(createId, used, kind);
  const { components, idMap } = cloneFoundationComponents(assemblyData, { createId: guarded });
  if (typeof transformClone === "function") {
    for (const k of ASSEMBLY_ARRAYS) for (const r of components[k] || []) transformClone(r, k);
  }
  // source_item_component_id is migrated-pole lineage the assembly model does
  // not remap (it is not a placement reference): point it at the cloned item
  // when the source travelled; leave it on the original row otherwise.
  for (const p of components.poles || []) {
    if (isId(p?.source_item_component_id) && idMap.has(p.source_item_component_id)) {
      p.source_item_component_id = idMap.get(p.source_item_component_id);
    }
  }
  const items = [...(project.items || []).map(cloneRow), ...(components.items || [])];
  const walls = [...(project.walls || []).map(cloneRow), ...(components.walls || [])];
  const poles = [...(project.poles || []).map(cloneRow), ...(components.poles || [])];
  const wallCaps = [...(project.wall_caps || []).map(cloneRow), ...(components.wall_caps || [])];
  const cabinets = [...(project.signage_cabinets || []).map(cloneRow), ...(components.signage_cabinets || [])];
  for (const p of components.poles || []) {
    p.foundation_idx = rebuildIndex(p.foundation_component_id, items);
  }
  for (const c of components.wall_caps || []) {
    c.wall_index = rebuildIndex(c.wall_component_id, walls);
    const wall = walls.find((w) => w?.component_id === c.wall_component_id);
    const segs = Array.isArray(wall?.shape?.segments) ? wall.shape.segments : [];
    c.segment_index = rebuildIndex(c.segment_component_id, segs);
  }
  for (const c of components.signage_cabinets || []) {
    if (c.mount === "pole") {
      c.pole_index = rebuildIndex(c.pole_component_id, poles);
      c.foundation_index = undefined;
    } else {
      c.foundation_index = rebuildIndex(c.foundation_component_id, items);
      c.pole_index = undefined;
    }
  }
  const patch = {};
  const clonedCounts = {};
  const pairs = [["items", items], ["walls", walls], ["poles", poles], ["wall_caps", wallCaps], ["signage_cabinets", cabinets]];
  for (const [k, arr] of pairs) {
    const n = (components[k] || []).length;
    clonedCounts[k] = n;
    if (n > 0) patch[k] = arr;
  }
  return { patch, components, idMap, clonedCounts };
}

const normalizeOffset = (v) => {
  if (v === undefined || v === null) return { ...DEFAULT_OFFSET_INCHES };
  if (fin(v)) return { x: v, z: v };
  if (isRecord(v)) {
    const x = v.x !== undefined ? v.x : v.x_inches;
    const z = v.z !== undefined ? v.z : v.z_inches;
    if ((x === undefined || fin(x)) && (z === undefined || fin(z))) {
      return { x: x ?? DEFAULT_OFFSET_INCHES.x, z: z ?? DEFAULT_OFFSET_INCHES.z };
    }
  }
  throw new Error("foundation duplicate: offset_inches must be a finite number or {x, z} inches");
};

const translateRow = (row, kind, off) => {
  if (kind === "items" || kind === "poles") {
    if (fin(row.x_inches)) row.x_inches += off.x;
    if (fin(row.z_inches)) row.z_inches += off.z;
  } else if (kind === "walls") {
    const pts = row?.shape?.points;
    if (Array.isArray(pts)) {
      for (const p of pts) {
        if (fin(p?.x)) p.x += off.x;
        if (fin(p?.z)) p.z += off.z;
      }
    }
  }
  // wall_caps / signage_cabinets carry no plan geometry — nothing to move.
};

// Duplicate the selected rows (or the whole assembly) with fresh component
// ids, remapped references, and a plan offset so the copy is not stacked
// invisibly on the source. Returns { patch, summary } — merge patch as
// {...prev, ...patch}; only arrays that gained rows are supplied.
export function duplicateFoundationAssembly(project, {
  component_ids,
  include_dependents = true,
  offset_inches,
  createId,
} = {}) {
  if (!isRecord(project)) throw new Error("foundation duplicate: project must be a record");
  if (typeof createId !== "function") throw new Error("foundation duplicate: createId(kind) factory is required");
  const off = normalizeOffset(offset_inches);
  const selected = selectRows(project, component_ids, include_dependents !== false);
  const subset = subsetOf(project, selected);
  const { patch, idMap, clonedCounts } = appendClonedFoundationAssemblies(project, subset, {
    createId,
    transformClone: (row, kind) => translateRow(row, kind, off),
  });
  return {
    patch,
    summary: {
      operation: "duplicate",
      offset_inches: off,
      duplicated: clonedCounts,
      rows_added: Object.values(clonedCounts).reduce((a, n) => a + n, 0),
      id_map: Object.fromEntries(idMap),
    },
  };
}

// Resolve the mirror line: an explicit coordinate (at), an item edge anchor
// (edge_of + edge — "mirror across a foundation edge"), or the layout canvas
// centerline when nothing is supplied.
const EDGE_ALIASES = {
  min_x: { axis: "x", at: (item, fp) => item.x_inches },
  left: { axis: "x", at: (item, fp) => item.x_inches },
  max_x: { axis: "x", at: (item, fp) => item.x_inches + fp.width },
  right: { axis: "x", at: (item, fp) => item.x_inches + fp.width },
  min_z: { axis: "z", at: (item, fp) => item.z_inches },
  top: { axis: "z", at: (item, fp) => item.z_inches },
  max_z: { axis: "z", at: (item, fp) => item.z_inches + fp.depth },
  bottom: { axis: "z", at: (item, fp) => item.z_inches + fp.depth },
};

const resolveMirrorLine = (project, { axis, at, edge_of, edge } = {}) => {
  if (edge_of !== undefined && edge_of !== null) {
    const item = (project.items || []).find((r) => r?.component_id === edge_of);
    if (!item) throw new Error("foundation mirror: edge_of must name a foundation item component_id");
    const fp = foundationLayoutFootprint(item);
    if (!fp || !fin(item.x_inches) || !fin(item.z_inches)) {
      throw new Error("foundation mirror: edge_of item needs a finite plan position and footprint");
    }
    const spec = EDGE_ALIASES[edge ?? "max_x"];
    if (!spec) throw new Error(`foundation mirror: unknown edge "${String(edge)}" (min_x|max_x|min_z|max_z or left|right|top|bottom)`);
    return { axis: spec.axis, at: spec.at(item, fp) };
  }
  const ax = axis === undefined || axis === null ? "x" : axis;
  if (ax !== "x" && ax !== "z") throw new Error('foundation mirror: axis must be "x" or "z"');
  const v = at === undefined || at === null
    ? (ax === "x" ? FOUNDATION_LAYOUT_WIDTH_INCHES / 2 : FOUNDATION_LAYOUT_DEPTH_INCHES / 2)
    : at;
  if (!fin(v)) throw new Error("foundation mirror: the mirror line (at) must be a finite inches value");
  return { axis: ax, at: v };
};

// Reflect one cloned row about the mirror line. Items reflect by footprint
// CENTER (corner storage + width/depth adjust) and flip rotation (any
// reflection reverses orientation: theta -> -theta). Poles reflect as points.
// Wall points reflect coordinate-wise; segment lengths are preserved exactly
// (reflection is an isometry), and caps/cabinets need no rewrite — they ride
// their remapped references. Returns true when any geometry changed.
const reflectRow = (row, kind, { axis, at }) => {
  const rc = (v) => 2 * at - v;
  let changed = false;
  if (kind === "items") {
    const fp = foundationLayoutFootprint(row);
    if (axis === "x") {
      if (fin(row.x_inches)) { row.x_inches = fp ? rc(row.x_inches) - fp.width : rc(row.x_inches); changed = true; }
    } else {
      if (fin(row.z_inches)) { row.z_inches = fp ? rc(row.z_inches) - fp.depth : rc(row.z_inches); changed = true; }
    }
    if (fin(row.rotation_degrees)) { row.rotation_degrees = normDeg(-row.rotation_degrees); changed = true; }
  } else if (kind === "poles") {
    if (axis === "x" && fin(row.x_inches)) { row.x_inches = rc(row.x_inches); changed = true; }
    if (axis === "z" && fin(row.z_inches)) { row.z_inches = rc(row.z_inches); changed = true; }
  } else if (kind === "walls") {
    const pts = row?.shape?.points;
    if (Array.isArray(pts)) {
      for (const p of pts) {
        if (axis === "x" && fin(p?.x)) { p.x = rc(p.x); changed = true; }
        if (axis === "z" && fin(p?.z)) { p.z = rc(p.z); changed = true; }
      }
    }
  }
  return changed;
};

// Mirror the selected rows (or the whole assembly) about a centerline or a
// foundation edge. mode "copy" (default) appends reflected clones with fresh
// ids — the CAD-style mirror copy; mode "reflect"/"in_place" reflects the
// selected rows in place keeping their ids (references keep working, so caps
// and cabinets ride their parents without a row edit). Returns { patch,
// summary }; only arrays containing reflected rows are supplied in-place,
// only arrays that gained rows are supplied in copy mode.
export function mirrorFoundationAssembly(project, {
  component_ids,
  include_dependents = true,
  axis,
  at,
  edge_of,
  edge,
  mode = "copy",
  createId,
} = {}) {
  if (!isRecord(project)) throw new Error("foundation mirror: project must be a record");
  const line = resolveMirrorLine(project, { axis, at, edge_of, edge });
  if (mode === "reflect" || mode === "in_place") {
    const selected = selectRows(project, component_ids, include_dependents !== false);
    const patch = {};
    const mirrored = {};
    let total = 0;
    for (const k of ASSEMBLY_ARRAYS) {
      let changed = 0;
      const next = (project[k] || []).map((r) => {
        const copy = cloneRow(r);
        if (selected[k].has(r) && isRecord(copy) && reflectRow(copy, k, line)) changed += 1;
        return copy;
      });
      if (changed > 0) {
        patch[k] = next;
        mirrored[k] = changed;
        total += changed;
      }
    }
    return {
      patch,
      summary: { operation: "mirror", mode: "in_place", axis: line.axis, at: line.at, mirrored, rows_mirrored: total },
    };
  }
  if (mode !== "copy") throw new Error('foundation mirror: mode must be "copy" or "reflect"');
  if (typeof createId !== "function") throw new Error("foundation mirror: copy mode requires a createId(kind) factory");
  const selected = selectRows(project, component_ids, include_dependents !== false);
  const subset = subsetOf(project, selected);
  const { patch, idMap, clonedCounts } = appendClonedFoundationAssemblies(project, subset, {
    createId,
    transformClone: (row, kind) => reflectRow(row, kind, line),
  });
  return {
    patch,
    summary: {
      operation: "mirror",
      mode: "copy",
      axis: line.axis,
      at: line.at,
      mirrored: clonedCounts,
      rows_added: Object.values(clonedCounts).reduce((a, n) => a + n, 0),
      id_map: Object.fromEntries(idMap),
    },
  };
}

// O-094 (CMP-H03) — bulk material change. Swaps a catalog material id across
// the assembly rows WHERE THAT MATERIAL FIELD ACTUALLY LIVES — the target
// catalog below is the applicability map: a concrete mix can only reach
// selected_concrete_id slots, a cap material only cap_inventory_id, and so
// on. Unknown targets fail closed; there is no free-form field write.
//
// Pure: the source project is never mutated and no price field is authored.
// Output is a template-patch-shaped delta — merge as {...prev, ...patch};
// only arrays that actually changed are supplied (absent keys preserve), and
// each supplied array replaces its whole list, matching
// prepareFoundationTemplatePatch patch semantics.
const isRecord = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const deepClone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
const cloneRow = (r) => {
  try {
    return deepClone(r);
  } catch {
    return isRecord(r) ? { ...r } : r;
  }
};

// Applicability catalog: material slot -> the row fields that hold that
// catalog id. items.selected_pole_id is the LEGACY item-level pole field
// (poleCalculator marks it advisory, not priced) — it still holds a pole
// material id, so a bulk pole swap rewrites it alongside poles[].pole_id.
// items.custom_concrete_cost_per_cy is a PRICE override, never a material id,
// and is deliberately excluded (its count is reported as an advisory so the
// caller can surface "custom price still applies" after a mix swap).
// project_concrete_type is a descriptive type string (e.g. "4000psi"), not a
// catalog id — not a bulk target.
export const FOUNDATION_BULK_MATERIAL_TARGETS = {
  concrete: {
    label: "Concrete mix",
    fields: { items: ["selected_concrete_id"] },
    project_field: "selected_concrete_id",
  },
  forming: {
    label: "Forming material",
    fields: { items: ["selected_forming_id"] },
  },
  wall_material: {
    label: "Wall material",
    fields: { walls: ["materialId"] },
  },
  internal_wall_material: {
    label: "Internal wall material",
    fields: { walls: ["internalMaterialId"] },
  },
  wall_cap: {
    label: "Wall cap material",
    fields: { wall_caps: ["cap_inventory_id"] },
  },
  pole: {
    label: "Pole material",
    fields: { poles: ["pole_id"], items: ["selected_pole_id"] },
  },
};

// Blank-equivalent current values: panels treat "", undefined, and null as
// "no selection", so all three normalize to "" for replace/fill matching.
const currentValue = (row, field) => {
  const v = row?.[field];
  return v === undefined || v === null ? "" : v;
};

// applyFoundationBulkMaterial(project, spec) -> { patch, summary }.
//   target   — a FOUNDATION_BULK_MATERIAL_TARGETS key (fail closed otherwise)
//   value    — the catalog material id to write; "" clears the selection
//   mode     — "all" (default): write every applicable slot in scope
//              "replace": only slots whose current value === from (from
//                         required, normalized like current values)
//              "fill_blank": only empty slots
//   include_project_default — targets with a project_field also update the
//              project-level default when it differs (default true); only
//              meaningful for "all"/"replace" intents — a project default
//              change accompanies any row write scope.
//   component_ids — optional row scope; only rows whose component_id is listed
//              are eligible (unknown ids are ignored, not errors: the set is a
//              filter, not a selection contract)
export function applyFoundationBulkMaterial(project, {
  target,
  value,
  mode = "all",
  from,
  include_project_default = true,
  component_ids,
} = {}) {
  if (!isRecord(project)) throw new Error("foundation bulk material: project must be a record");
  const spec = FOUNDATION_BULK_MATERIAL_TARGETS[target];
  if (!spec) {
    throw new Error(
      `foundation bulk material: unknown target ${JSON.stringify(target)} — valid targets: ${Object.keys(FOUNDATION_BULK_MATERIAL_TARGETS).join(", ")}`,
    );
  }
  if (typeof value !== "string") throw new Error("foundation bulk material: value must be a material id string (\"\" clears)");
  if (mode !== "all" && mode !== "replace" && mode !== "fill_blank") {
    throw new Error('foundation bulk material: mode must be "all", "replace", or "fill_blank"');
  }
  if (mode === "replace" && typeof from !== "string") {
    throw new Error('foundation bulk material: mode "replace" requires a from value (string; "" matches blanks)');
  }
  if (component_ids !== undefined && component_ids !== null && !Array.isArray(component_ids)) {
    throw new Error("foundation bulk material: component_ids must be an array when supplied");
  }
  const scope = Array.isArray(component_ids) ? new Set(component_ids) : null;
  const inScope = (row) => !scope || (typeof row?.component_id === "string" && scope.has(row.component_id));

  const shouldWrite = (current) => {
    if (mode === "all") return current !== value;
    if (mode === "replace") return current === from && current !== value;
    return current === "" && value !== ""; // fill_blank
  };

  const patch = {};
  const rowsChanged = {};
  const fieldsTouched = new Set();
  let customPriceRows = 0;

  for (const [kind, fields] of Object.entries(spec.fields)) {
    const rows = project[kind];
    if (!Array.isArray(rows) || rows.length === 0) continue;
    let changed = 0;
    const next = rows.map((r) => {
      if (!isRecord(r) || !inScope(r)) return cloneRow(r);
      let edited = null;
      for (const f of fields) {
        const cur = currentValue(r, f);
        if (shouldWrite(cur)) {
          if (!edited) edited = cloneRow(r);
          edited[f] = value;
          fieldsTouched.add(`${kind}.${f}`);
        }
      }
      if (edited) {
        changed += 1;
        if (kind === "items" && r.custom_concrete_cost_per_cy !== undefined && r.custom_concrete_cost_per_cy !== null) {
          customPriceRows += 1;
        }
        return edited;
      }
      return cloneRow(r);
    });
    if (changed > 0) {
      patch[kind] = next;
      rowsChanged[kind] = changed;
    }
  }

  // The project-level default participates under the same mode rules — in
  // "replace" mode it moves only when it currently holds `from`, in
  // "fill_blank" only when blank. It is project state, not a row, so
  // component_ids scope does not apply to it.
  let projectDefaultChanged = false;
  if (spec.project_field && include_project_default !== false) {
    const normalized = currentValue(project, spec.project_field);
    if (shouldWrite(normalized)) {
      patch[spec.project_field] = value;
      projectDefaultChanged = true;
      fieldsTouched.add(`project.${spec.project_field}`);
    }
  }

  return {
    patch,
    summary: {
      operation: "bulk_material",
      target,
      label: spec.label,
      value,
      mode,
      ...(mode === "replace" ? { from } : {}),
      rows_changed: rowsChanged,
      rows_total: Object.values(rowsChanged).reduce((a, n) => a + n, 0),
      project_default_changed: projectDefaultChanged,
      fields_touched: [...fieldsTouched],
      // Advisory: changed items carrying a per-item custom concrete price keep
      // it — the mix swap does not reprice the override.
      custom_price_rows_kept: customPriceRows,
    },
  };
}

import { foundationInputNumber } from "./foundationGeometryInputs";

const isRecord = value => value !== null && typeof value === "object"
  && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const scalar = value => value === null || ["undefined", "string", "number", "boolean"].includes(typeof value) ? value : NaN;
const numeric = value => {
  if (typeof value === "string" && !value.trim()) return null;
  const parsed = foundationInputNumber(value);
  return parsed !== null ? parsed : scalar(value);
};

export function createFoundationReinforcementDraft(item = {}) {
  const accepted = item?.reinforcement_calculation_version === 2;
  const design = accepted && isRecord(item.reinforcement_design) ? structuredClone(item.reinforcement_design) : {
    version: 2, bar_diameter_inches: "",
    cover_inches: { side: "", top: "", bottom: "" },
    supports: { mode: "unconfigured", reason: "" },
    spread: { mats: [], inter_mat_ties: [] },
    pillar: { hoops: [], longitudinal: { count: "", radius_inches: "", bottom_end_inches: "", top_end_inches: "" } },
  };
  return {
    schema_version: 1, design,
    material: accepted && isRecord(item.reinforcement_material) ? structuredClone(item.reinforcement_material) : { kind: "" },
    overrides: { quantity_ft: item?.custom_rebar_qty ?? null, cost_per_ft: item?.custom_rebar_cost_per_ft ?? null },
  };
}

// Keep raw text in the draft; typed values exist only for fresh preview/acceptance.
export function prepareFoundationReinforcementDraft(draft) {
  const issues = [];
  const issue = (field, message) => issues.push({ field, code: "reinforcement_draft_invalid", severity: "error", message });
  if (!isRecord(draft) || draft.schema_version !== 1) {
    issue("schema_version", "A supported version-1 reinforcement proposal is required.");
    return { prepared: null, issues };
  }
  const raw = draft.design;
  if (!isRecord(raw)) {
    issue("design", "The proposal needs a reinforcement design object.");
    return { prepared: null, issues };
  }
  const numbers = (record, fields) => Object.fromEntries(fields.map(field => [field, numeric(record?.[field])]));
  const reference = value => typeof value === "string" ? value : scalar(value);
  const list = (value, field, maximum, map) => {
    if (value == null) return value;
    if (!Array.isArray(value) || value.length > maximum) {
      issue(field, `Use an explicit list of at most ${maximum} records.`);
      return null;
    }
    return value.map((record, index) => {
      if (!isRecord(record)) {
        issue(`${field}.${index}`, "Each proposal row must be an object.");
        return null;
      }
      return map(record);
    });
  };
  const design = {
    version: scalar(raw.version), bar_diameter_inches: numeric(raw.bar_diameter_inches),
    cover_inches: numbers(raw.cover_inches, ["side", "top", "bottom"]),
    supports: { mode: scalar(raw.supports?.mode), reason: scalar(raw.supports?.reason) },
    spread: {
      mats: list(raw.spread?.mats, "design.spread.mats", 256, record => ({
        id: reference(record.id), ...numbers(record, ["bearing_elevation_inches", "max_spacing_x_inches", "max_spacing_z_inches"]),
      })),
      inter_mat_ties: list(raw.spread?.inter_mat_ties, "design.spread.inter_mat_ties", 4096, record => ({
        id: reference(record.id), from_mat_id: reference(record.from_mat_id), to_mat_id: reference(record.to_mat_id),
        ...numbers(record, ["x_inches", "z_inches", "cut_length_inches"]),
      })),
    },
    pillar: {
      hoops: list(raw.pillar?.hoops, "design.pillar.hoops", 256, record => ({
        id: reference(record.id), ...numbers(record, ["center_y_inches", "centerline_diameter_inches", "cut_allowance_inches"]),
      })),
      longitudinal: numbers(raw.pillar?.longitudinal, ["count", "radius_inches", "bottom_end_inches", "top_end_inches"]),
    },
  };
  const source = isRecord(draft.material) ? draft.material : {};
  const material = {
    kind: scalar(source.kind), inventory_id: reference(source.inventory_id),
    name: scalar(source.name), reason: scalar(source.reason), unit: scalar(source.unit),
    ...numbers(source, ["bar_diameter_inches", "weight_lb_per_ft", "cost_per_ft"]),
  };
  const overrides = isRecord(draft.overrides) ? draft.overrides : {};
  if (draft.overrides != null && !isRecord(draft.overrides)) issue("overrides", "Proposal overrides must be an object.");
  return {
    prepared: {
      schema_version: 1, design, material,
      overrides: { quantity_ft: numeric(overrides.quantity_ft ?? null), cost_per_ft: numeric(overrides.cost_per_ft ?? null) },
    },
    issues,
  };
}

import { calcItem } from "./foundationCalc";
import { foundationItemInputIssues } from "./foundationInputValidation";
import { foundationItemCatalogIssues } from "./foundationCatalogIntegrity";
import { prepareFoundationReinforcementDraft } from "./foundationReinforcementDraft";
import { calculateFoundationReinforcementItemProjection } from "./foundationReinforcementItemProjection";
import { encodeFoundationReinforcementBasis } from "./foundationReinforcementBasisKey";

const isRecord = value => value !== null && typeof value === "object"
  && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const identifier = value => typeof value === "string" && Boolean(value.trim()) && value.trim() === value && value.length <= 256;
const finite = value => typeof value === "number" && Number.isFinite(value);
const amount = (item, key) => finite(item?.[key]) ? item[key] : null;
const version = item => item.reinforcement_calculation_version == null ? 1 : item.reinforcement_calculation_version;
const DERIVED_ITEM_FIELDS = new Set([
  "concrete_volume_cy", "excavation_volume_cy", "concrete_bags", "rebar_feet", "rebar_weight_lbs",
  "concrete_cost", "concrete_rate", "rebar_cost", "rebar_rate", "excavation_cost", "excavation_hours",
  "forming_cost", "forming_qty", "pouring_cost", "finishing_cost", "finishing_hours", "item_total_cost",
  "rebar_material_cost", "rebar_labor_cost", "rebar_labor_hours", "rebar_geometry_feet",
  "rebar_geometry_weight_lbs", "rebar_connection_count", "reinforcement_cost_snapshot", "reinforcement_proposal",
]);
const DERIVED_PROJECT_FIELDS = new Set([
  "grand_total", "total_concrete_cost", "total_rebar_cost", "total_excavation_cost", "total_labor_cost",
  "total_equipment_cost", "total_forming_materials_cost", "total_pole_cost", "total_pole_painting_cost",
  "total_brick_cost", "total_fill_cost", "total_wall_cost", "total_wall_cap_cost",
  "total_signage_cabinet_cost", "total_landscape_cost", "concrete_delivery_snapshot", "builder_calculation",
]);
const rawProject = project => Object.fromEntries(Object.entries(project)
  .filter(([key]) => !DERIVED_PROJECT_FIELDS.has(key))
  .map(([key, value]) => [key, key === "items"
    ? value.map(item => Object.fromEntries(Object.entries(item).filter(([field]) => !DERIVED_ITEM_FIELDS.has(field))))
    : value]));
const compare = (before, proposed) => {
  const delta = before === null || proposed === null ? null : proposed - before;
  return { before, proposed, delta: finite(delta) ? delta : null };
};

// Local preview only. Parent supplies its non-undoable acknowledged source/context.
// Fingerprint equality is stale-result protection, never server authorization.
export function createFoundationReinforcementProposal({
  project, savedProject, inventory = [], settings = {}, context, componentId, rawDraft, proposalId,
  acknowledgments = {},
} = {}) {
  const issues = [];
  const issue = (code, message) => issues.push({ code, message, severity: "error", scope: "proposal" });
  const unavailable = () => ({
    version: 1, id: proposalId, componentId, basisKey: null, canAccept: false,
    engineeringApproved: false, issues, projection: null, comparisons: null,
  });
  if (!isRecord(project) || !Array.isArray(project.items) || project.items.some(item => !isRecord(item))
    || !isRecord(savedProject) || !Array.isArray(savedProject.items) || savedProject.items.some(item => !isRecord(item))) {
    issue("reinforcement_proposal_source_required", "Current raw design and acknowledged saved source are required.");
    return unavailable();
  }
  if (!isRecord(context) || context.loaded !== true || !identifier(context.ownerId) || !identifier(context.sourceId)
    || context.sourceId !== project.id || savedProject.id !== project.id
    || !identifier(context.sourceUpdatedAt) || savedProject.updated_date !== context.sourceUpdatedAt
    || !Number.isSafeInteger(context.generation) || context.generation < 0
    || !Number.isSafeInteger(context.editRevision) || context.editRevision < 0
    || !(context.estimateId === null || identifier(context.estimateId))
    || (context.estimateId !== null && !identifier(context.estimateUpdatedAt))) {
    issue("reinforcement_proposal_context_unavailable", "Reload or resolve the current owner, source acknowledgment and linked estimate revision before previewing.");
    return unavailable();
  }
  if (!identifier(componentId) || !identifier(proposalId)) {
    issue("reinforcement_proposal_identity_required", "Stable component and opaque proposal identities are required.");
    return unavailable();
  }
  const matches = project.items.filter(item => item.component_id === componentId);
  if (matches.length !== 1) {
    issue("reinforcement_proposal_component_ambiguous", "The target component is missing or has a duplicate ID.");
    return unavailable();
  }
  const item = matches[0], savedMatches = savedProject.items.filter(record => record.component_id === componentId);
  const savedItem = savedMatches.length === 1 ? savedMatches[0] : null;
  if (![1, 2].includes(version(item))) {
    issue("reinforcement_proposal_version_unsupported", "An unsupported active calculation version cannot be silently replaced.");
    return unavailable();
  }
  const preparation = prepareFoundationReinforcementDraft(rawDraft);
  issues.push(...preparation.issues);
  if (!preparation.prepared || preparation.issues.some(value => value.severity === "error")) return unavailable();
  const prepared = preparation.prepared;
  const calculate = (source, design, material, quantityOverride, rateOverride) =>
    calculateFoundationReinforcementItemProjection({ item: source, design, material, inventory, settings,
      excavationMethod: project.excavation_method, quantityOverride, rateOverride });
  const projection = calculate(item, prepared.design, prepared.material, prepared.overrides.quantity_ft, prepared.overrides.cost_per_ft);
  issues.push(...projection.issues);
  let current, currentProvenance;
  if (version(item) === 2) {
    const active = calculate(item, item.reinforcement_design, item.reinforcement_material, item.custom_rebar_qty, item.custom_rebar_cost_per_ft);
    current = active.canApplyToEstimate ? active.itemCost : null;
    currentProvenance = current ? "Current version-2 calculation" : "Acknowledged saved amount";
    current ??= savedItem;
  } else {
    const blocked = !isRecord(settings) || !Array.isArray(inventory) || inventory.some(row => !isRecord(row))
      || foundationItemInputIssues(item).length || foundationItemCatalogIssues(item, inventory).length;
    current = blocked ? savedItem : calcItem(item, project, inventory, settings, savedItem);
    currentProvenance = blocked ? "Acknowledged saved amount" : "Current legacy calculation";
  }
  const comparisons = {
    steel: compare(amount(current, "rebar_cost"), amount(projection.itemCost, "rebar_cost")),
    item: compare(amount(current, "item_total_cost"), amount(projection.itemCost, "item_total_cost")),
    savedSteel: amount(savedItem, "rebar_cost"), savedItem: amount(savedItem, "item_total_cost"),
    currentProvenance, savedProvenance: "Acknowledged saved source; not a customer selling price",
  };
  if (comparisons.steel.delta === null || comparisons.item.delta === null) {
    issue("reinforcement_proposal_delta_unavailable", "Both current steel and full item cost deltas must be known before replacement.");
  }
  const warningCodes = [...new Set(projection.issues.filter(value => value.severity === "warning").map(value => value.code))].sort();
  const warningAcknowledgments = Array.isArray(acknowledgments?.warningCodes) ? acknowledgments.warningCodes : [];
  if (acknowledgments?.preliminary !== true || warningCodes.some(code => !warningAcknowledgments.includes(code))) {
    issue("reinforcement_proposal_acknowledgment_required", "Explicitly acknowledge the preliminary-only status and every current warning before acceptance.");
  }
  let basisKey;
  try {
    basisKey = encodeFoundationReinforcementBasis({
      protocolRevision: 1, calculationRevision: "foundation-v2-proposal-1",
      context, componentId, project: rawProject(project), savedProject, inventory, settings,
      rawDraft, prepared, acknowledgments, proposedItemCost: projection.itemCost,
      comparisons,
    });
  } catch (error) {
    issue("reinforcement_proposal_basis_unavailable", error.message);
    basisKey = null;
  }
  return {
    version: 1, id: proposalId, componentId, basisKey, prepared, projection, comparisons, warningCodes, issues,
    engineeringApproved: false,
    canAccept: Boolean(basisKey && projection.canApplyToEstimate && !issues.some(value => value.severity === "error")),
  };
}

// Return one immutable parent commit; no history pushes, saves, or Builder writes.
export function acceptFoundationReinforcementProposal({ proposal, requestedId, activeProposalId, acceptedAt, ...currentInputs } = {}) {
  const reject = (code, message) => ({ ok: false, code, message, project: null });
  if (proposal?.version !== 1 || proposal.canAccept !== true || !identifier(requestedId)
    || requestedId !== activeProposalId || requestedId !== proposal.id
    || !identifier(proposal.componentId) || typeof proposal.basisKey !== "string" || !proposal.basisKey) {
    return reject("reinforcement_proposal_not_acceptable", "Use the exact currently eligible proposal; no design or price was changed.");
  }
  if (typeof acceptedAt !== "string" || !Number.isFinite(Date.parse(acceptedAt))) {
    return reject("reinforcement_acceptance_time_required", "An explicit acceptance timestamp is required.");
  }
  const fresh = createFoundationReinforcementProposal({ ...currentInputs, componentId: proposal.componentId, proposalId: requestedId });
  if (!fresh.basisKey || fresh.basisKey !== proposal.basisKey) {
    return reject("reinforcement_proposal_stale", "Inputs, context, source, settings or catalog changed. Refresh and review the full delta again.");
  }
  if (!fresh.canAccept) return reject("reinforcement_proposal_not_ready", "The fresh calculation is not eligible for replacement.");
  const { prepared, projection } = fresh;
  const nextItems = currentInputs.project.items.map(item => {
    if (item.component_id !== proposal.componentId) return item;
    const next = { ...item, ...projection.itemCost,
      reinforcement_calculation_version: 2,
      reinforcement_design: structuredClone(prepared.design),
      reinforcement_material: structuredClone(prepared.material),
      custom_rebar_qty: prepared.overrides.quantity_ft,
      custom_rebar_cost_per_ft: prepared.overrides.cost_per_ft,
      reinforcement_cost_snapshot: {
        version: 1, calculation_version: 2, engineering_approved: false,
        amounts: structuredClone(projection.reinforcement.steel.amounts),
        material: structuredClone(projection.reinforcement.materialSnapshot),
        basis: structuredClone(projection.reinforcement.basis),
        rate_sources: structuredClone(projection.reinforcement.rateSources),
      },
      reinforcement_acceptance: {
        version: 1, proposal_id: requestedId, accepted_at: acceptedAt,
        owner_id: currentInputs.context.ownerId, source_id: currentInputs.context.sourceId,
        component_id: proposal.componentId,
        source_updated_at: currentInputs.context.sourceUpdatedAt,
        acknowledged_warning_codes: [...fresh.warningCodes], engineering_approved: false,
      },
    };
    delete next.reinforcement_proposal;
    return next;
  });
  return { ok: true, code: "reinforcement_proposal_accepted_locally", project: { ...currentInputs.project, items: nextItems }, proposal: fresh };
}

const MAX_DEPTH = 32;
const MAX_NODES = 1000000;
const MAX_CHARACTERS = 16000000;

// Exact local stale-result equality, not a hash, authorization, or a CAS token.
// The caller owns selecting raw inputs/context and removing derived metadata.
export function encodeFoundationReinforcementBasis(value) {
  const chunks = [], ancestors = new Set();
  let nodes = 0, characters = 0;
  const append = text => {
    characters += text.length;
    if (characters > MAX_CHARACTERS) throw new RangeError("Reinforcement preview basis is too large.");
    chunks.push(text);
  };
  const visit = (current, depth) => {
    if (depth > MAX_DEPTH || ++nodes > MAX_NODES) throw new RangeError("Reinforcement preview basis exceeds the supported traversal limit.");
    if (current === null) { append("null;"); return; }
    switch (typeof current) {
      case "undefined": append("undefined;"); return;
      case "boolean": append(current ? "boolean:true;" : "boolean:false;"); return;
      case "string": append(`string:${JSON.stringify(current)};`); return;
      case "number":
        if (!Number.isFinite(current)) throw new TypeError("Reinforcement preview basis contains a nonfinite number.");
        append(`number:${Object.is(current, -0) ? "-0" : current};`); return;
      case "object": break;
      default: throw new TypeError("Reinforcement preview basis contains an unsupported value.");
    }
    if (ancestors.has(current)) throw new TypeError("Reinforcement preview basis contains a cycle.");
    if (Object.getOwnPropertySymbols(current).length) throw new TypeError("Reinforcement preview basis cannot contain symbol keys.");
    const array = Array.isArray(current);
    if (!array && ![Object.prototype, null].includes(Object.getPrototypeOf(current))) {
      throw new TypeError("Reinforcement preview basis requires plain objects and arrays.");
    }
    const keys = Object.getOwnPropertyNames(current);
    const child = key => {
      const descriptor = Object.getOwnPropertyDescriptor(current, key);
      if (!descriptor || !Object.hasOwn(descriptor, "value") || !descriptor.enumerable) {
        throw new TypeError("Reinforcement preview basis cannot contain hidden properties or accessors.");
      }
      visit(descriptor.value, depth + 1);
    };
    ancestors.add(current);
    if (array) {
      if (keys.length !== current.length + 1 || !keys.includes("length")) {
        throw new TypeError("Reinforcement preview basis requires dense arrays without extra properties.");
      }
      append(`array:${current.length}[`);
      for (let index = 0; index < current.length; index++) child(String(index));
      append("];");
    } else {
      keys.sort();
      append(`object:${keys.length}{`);
      for (const key of keys) { append(`${JSON.stringify(key)}:`); child(key); }
      append("};");
    }
    ancestors.delete(current);
  };
  visit(value, 0);
  return chunks.join("");
}

import { useCallback, useEffect, useRef, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Copy, Link2, Loader2, Mail, MessageSquare, Send } from "lucide-react";

export const invokePortal = async (sessionToken, body) => {
  const r = await base44.functions.invoke("customerPortalAction", { session_token: sessionToken, ...body });
  const data = r?.data || r;
  if (!data?.success) throw new Error(data?.error || "Request failed.");
  return data;
};

export const MESSAGE_KIND_LABELS = {
  estimate_approved: "Quote approved",
  estimate_revision_requested: "Revision requested",
  payment_notice: "Payment notice",
  job_revision_requested: "Job change requested",
};

export default function PortalPanel({ sessionToken, customerId }) {
  const [thread, setThread] = useState(null);
  const [links, setLinks] = useState([]);
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [copied, setCopied] = useState("");
  const [emailed, setEmailed] = useState("");
  const replyKeyRef = useRef(crypto.randomUUID());
  const endRef = useRef(null);

  const load = useCallback(async () => {
    try {
      const data = await invokePortal(sessionToken, { action: "list_thread", customer_id: customerId });
      setThread(data.messages || []);
      setLinks(data.links || []);
    } catch (err) {
      setError(err?.message || "Portal data could not load.");
      setThread([]);
    }
  }, [sessionToken, customerId]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => { endRef.current?.scrollIntoView(); }, [thread?.length]);

  const run = async (label, body, after) => {
    if (busy) return;
    setBusy(label);
    setError("");
    try {
      const data = await invokePortal(sessionToken, body);
      await load();
      await after?.(data);
    } catch (err) {
      setError(err?.message || "Portal action failed.");
    } finally {
      setBusy("");
    }
  };

  const customerLink = links.find((l) => l.kind === "customer" && l.usable && !l.revoked);
  const portalUrl = customerLink ? `${window.location.origin}/customerportal?token=${encodeURIComponent(customerLink.token)}` : "";
  const copy = async (url, key) => { try { await navigator.clipboard.writeText(url); setCopied(key); } catch { /* clipboard unavailable */ } };
  const unread = (thread || []).filter((m) => m.author_side === "customer" && !m.read_by_staff).length;

  if (thread === null) return null;
  return (
    <div className="rounded-lg border border-blue-200 bg-blue-50/50 p-3 sm:col-span-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-blue-800">
          <MessageSquare className="h-3.5 w-3.5" />Customer portal{unread > 0 ? ` · ${unread} new` : ""}
        </h3>
        {!customerLink ? (
          <button type="button" disabled={Boolean(busy)} onClick={() => run("link", { action: "create_link", kind: "customer", customer_id: customerId, creation_request_key: crypto.randomUUID() }, async (d) => {
            const link = d?.link;
            if (link) await copy(`${window.location.origin}/customerportal?token=${encodeURIComponent(link.token || d.token)}`, "new");
          })}
            className="inline-flex h-8 items-center gap-1.5 rounded-md bg-blue-600 px-2.5 text-[11px] font-semibold text-white hover:bg-blue-700 disabled:opacity-50">
            {busy === "link" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Link2 className="h-3.5 w-3.5" />}Create portal link
          </button>
        ) : (
          <div className="flex items-center gap-1.5">
            <button type="button" onClick={() => copy(portalUrl, "link")}
              className="inline-flex h-8 items-center gap-1 rounded-md border border-blue-300 bg-white px-2.5 text-[11px] font-semibold text-blue-700 hover:bg-blue-100">
              <Copy className="h-3 w-3" />{copied === "link" ? "Copied" : "Copy link"}
            </button>
            <button type="button" disabled={Boolean(busy)} onClick={() => run("email", { action: "email_link", customer_id: customerId, portal_base: window.location.origin }, (d) => { if (d?.sent_to) setEmailed(d.sent_to); })}
              className="inline-flex h-8 items-center gap-1 rounded-md border border-blue-300 bg-white px-2.5 text-[11px] font-semibold text-blue-700 hover:bg-blue-100 disabled:opacity-50">
              {busy === "email" ? <Loader2 className="h-3 w-3 animate-spin" /> : <Mail className="h-3 w-3" />}Email link
            </button>
            <button type="button" disabled={Boolean(busy)} onClick={() => { if (window.confirm("Revoke this customer's portal link? They will lose access immediately.")) run("revoke", { action: "revoke_link", link_id: customerLink.id }); }}
              className="inline-flex h-8 items-center rounded-md border border-red-300 bg-white px-2.5 text-[11px] font-semibold text-red-600 hover:bg-red-50 disabled:opacity-50">
              Revoke
            </button>
          </div>
        )}
      </div>
      {customerLink && (
        <p className="mt-1 text-[11px] text-blue-800/70">
          {customerLink.open_count > 0 ? `Opened ${customerLink.open_count}×${customerLink.last_opened_at ? ` · last ${new Date(customerLink.last_opened_at).toLocaleDateString()}` : ""}` : "Not opened yet"} · expires {customerLink.expires_at ? new Date(customerLink.expires_at).toLocaleDateString() : "never"}
          {emailed && <span className="ml-1 font-semibold text-emerald-700">· link emailed to {emailed}</span>}
        </p>
      )}

      <div className="mt-2 max-h-56 space-y-2 overflow-y-auto rounded-md border border-blue-100 bg-white p-2.5">
        {thread.length === 0 && <p className="py-3 text-center text-xs text-gray-400">No portal activity yet.</p>}
        {thread.map((m) => (
          <div key={m.id} className={`flex ${m.author_side === "staff" ? "justify-end" : "justify-start"}`}>
            <div className={`max-w-[85%] rounded-lg px-2.5 py-1.5 text-xs ${m.author_side === "staff" ? "bg-blue-600 text-white" : "bg-gray-100 text-gray-800"}`}>
              {MESSAGE_KIND_LABELS[m.kind] && (
                <p className={`text-[9px] font-bold uppercase tracking-wide ${m.author_side === "staff" ? "text-blue-200" : "text-amber-700"}`}>{MESSAGE_KIND_LABELS[m.kind]}</p>
              )}
              <p className={`text-[9px] font-semibold uppercase tracking-wide ${m.author_side === "staff" ? "text-blue-200" : "text-gray-500"}`}>
                {m.author_side === "staff" ? m.author_name || "Staff" : "Customer"}{m.related_label ? ` · re: ${m.related_label}` : ""}
              </p>
              <p className="whitespace-pre-wrap">{m.body}</p>
              {m.attachment_url && (
                <a href={m.attachment_url} target="_blank" rel="noreferrer" className={`mt-0.5 inline-block text-[10px] underline ${m.author_side === "staff" ? "text-blue-100" : "text-blue-600"}`}>
                  {m.attachment_name || "Attachment"}
                </a>
              )}
              <p className={`mt-0.5 text-[9px] ${m.author_side === "staff" ? "text-blue-200" : "text-gray-400"}`}>
                {m.created_date ? new Date(m.created_date).toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }) : ""}
              </p>
            </div>
          </div>
        ))}
        <div ref={endRef} />
      </div>
      <div className="mt-2 flex gap-2">
        <input value={draft} onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && draft.trim()) { run("reply", { action: "reply_message", customer_id: customerId, body: draft.trim(), creation_request_key: replyKeyRef.current }, () => { replyKeyRef.current = crypto.randomUUID(); setDraft(""); }); } }}
          placeholder={customerLink ? "Reply to the customer…" : "Create a portal link to enable replies"}
          disabled={!customerLink}
          className="h-9 flex-1 rounded-md border border-gray-300 px-2.5 text-xs disabled:bg-gray-100" />
        <button type="button" disabled={!customerLink || Boolean(busy) || !draft.trim()}
          onClick={() => run("reply", { action: "reply_message", customer_id: customerId, body: draft.trim(), creation_request_key: replyKeyRef.current }, () => { replyKeyRef.current = crypto.randomUUID(); setDraft(""); })}
          className="inline-flex h-9 w-9 items-center justify-center rounded-md bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50">
          {busy === "reply" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}
        </button>
      </div>
      {error && <div className="mt-1.5 text-[11px] font-medium text-red-600">{error}</div>}
    </div>
  );
}

// Pure utility functions for applying tier markups + volume discounts to project costs.
// Does NOT mutate project entities — produces a marked-up summary breakdown.

/**
 * Get a tier's markup multiplier for a given category_key.
 * Falls back to 1.0 (no markup) when the value is missing or non-positive.
 * Values between 0 and 1 are valid discount markups and are honored — only
 * ≤0 and non-numeric entries are treated as "not configured".
 */
export function getMarkup(tier, categoryKey) {
  if (!tier || !tier.markups) return 1.0;
  const v = tier.markups[categoryKey];
  return typeof v === 'number' && v > 0 ? v : 1.0;
}

/**
 * Parse volume discount brackets from Settings records.
 * Returns array of {min, pct} sorted high-to-low so we can pick the highest qualifying bracket.
 */
export function parseVolumeDiscountBrackets(settings) {
  const get = (name) => {
    const s = settings.find(x => x.setting_name === name);
    return s ? parseFloat(s.setting_value) : null;
  };
  const brackets = [];
  for (let i = 1; i <= 4; i++) {
    const min = get(`volume_discount_bracket_${i}_min`);
    const pct = get(`volume_discount_bracket_${i}_pct`);
    if (min !== null && pct !== null) brackets.push({ min, pct });
  }
  return brackets.sort((a, b) => b.min - a.min);
}

/**
 * Parse the list of category keys eligible for volume discount.
 */
export function parseVolumeDiscountCategories(settings) {
  const s = settings.find(x => x.setting_name === 'volume_discount_applies_to');
  if (!s) return [];
  return s.setting_value.split(',').map(x => x.trim()).filter(Boolean);
}

/**
 * Given an eligible subtotal, find the highest qualifying volume discount %.
 */
export function getVolumeDiscountPct(eligibleSubtotal, brackets) {
  for (const b of brackets) {
    if (eligibleSubtotal >= b.min) return b.pct;
  }
  return 0;
}

/**
 * Apply tier markup + volume discount to a list of cost lines.
 *
 * @param {Array<{label, cost, category_key, module}>} lines
 * @param {Object} tier - MarkupTier record
 * @param {Object} settings - { brackets, eligibleCategoryKeys }
 * @returns {Object} { lines: [...withMarkupApplied], totals: {...} }
 */
// Skip-recompute memo (#414): identical line/tier objects with identical
// settings content return the last result without re-running the markup
// waterfall. WeakMap on lines (a new array = new payload = fresh compute).
const _applyCache = new WeakMap();

export function applyMarkups(lines, tier, settings) {
  if (!lines || typeof lines !== "object") return _applyMarkupsComputed(lines, tier, settings);
  const settingsKey = JSON.stringify(settings || {});
  let byTier = _applyCache.get(lines);
  const hit = byTier?.get(tier);
  if (hit && hit.key === settingsKey) return hit.out;
  const out = _applyMarkupsComputed(lines, tier, settings);
  if (!byTier) { byTier = new Map(); _applyCache.set(lines, byTier); }
  byTier.set(tier, { key: settingsKey, out });
  return out;
}

function _applyMarkupsComputed(lines, tier, settings) {
  const { brackets = [], eligibleCategoryKeys = [], categoryFlags = {} } = settings || {};
  const isDiscountEligible = (key) => eligibleCategoryKeys.includes(key) && categoryFlags[key] !== false;

  // First pass: compute marked-up cost per line (no volume discount yet)
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const markup = getMarkup(tier, line.category_key);
    const markedCost = cost * markup;
    return {
      ...line,
      cost,
      markup_multiplier: markup,
      marked_up_cost: markedCost,
    };
  });

  // Compute eligible subtotal for volume discount
  const eligibleSubtotal = marked
    .filter(l => isDiscountEligible(l.category_key))
    .reduce((sum, l) => sum + l.marked_up_cost, 0);

  const volumeDiscountPct = getVolumeDiscountPct(eligibleSubtotal, brackets);
  const volumeDiscountFactor = 1 - (volumeDiscountPct / 100);

  // Second pass: apply volume discount only to eligible lines
  const finalLines = marked.map(line => {
    const isEligible = isDiscountEligible(line.category_key);
    const final = isEligible ? line.marked_up_cost * volumeDiscountFactor : line.marked_up_cost;
    return {
      ...line,
      volume_discount_applied: isEligible ? volumeDiscountPct : 0,
      final_cost: final,
    };
  });

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);
  const markedSubtotal = finalLines.reduce((s, l) => s + l.marked_up_cost, 0);
  const grandTotal = finalLines.reduce((s, l) => s + l.final_cost, 0);

  // Readability merge: collapse lines sharing a category_key into one row.
  // Same-category lines always share markup multiplier + discount eligibility,
  // so summing cost fields is exact. Per-item detail stays in detail_lines.
  const mergedLines = [];
  const byKey = new Map();
  for (const l of finalLines) {
    const key = l.category_key || "";
    const existing = byKey.get(key);
    if (!existing) {
      const g = { ...l, merged_count: 1, base_label: l.label };
      byKey.set(key, g);
      mergedLines.push(g);
    } else {
      existing.merged_count += 1;
      existing.cost += l.cost;
      existing.marked_up_cost += l.marked_up_cost;
      existing.final_cost += l.final_cost;
      existing.label = `${existing.base_label} (+${existing.merged_count - 1} merged)`;
    }
  }

  return {
    lines: mergedLines,
    detail_lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      eligible_subtotal: eligibleSubtotal,
      volume_discount_pct: volumeDiscountPct,
      grand_total: grandTotal,
    },
  };
}

/**
 * Cost-Plus pricing engine — alternative to applyMarkups().
 *
 * Pipeline (per line):
 *   1. category_markup_pct (optional)  → cost × (1 + pct/100)
 *   2. labor_multiplier                → applied only to lines flagged as labor
 *   3. overhead_percent                → flat % on the marked subtotal
 *   4. profit_percent                  → flat % on the post-overhead subtotal
 *
 * @param {Array<{label, cost, category_key, module, is_labor?}>} lines
 * @param {Object} config - CostPlusConfig record
 * @returns {Object} { lines: [...], totals: {...} }
 */
export function applyCostPlus(lines, config) {
  const cfg = config || {};
  const laborMult = Number(cfg.labor_multiplier) || 1;
  const overheadPct = Number(cfg.overhead_percent) || 0;
  const profitPct = Number(cfg.profit_percent) || 0;
  const catMarkups = cfg.category_markups || {};

  // 1+2: per-line category markup, then labor burden on labor lines
  const marked = lines.map(line => {
    const cost = Number(line.cost) || 0;
    const catPct = Number(catMarkups[line.category_key]) || 0;
    const afterCatMarkup = cost * (1 + catPct / 100);
    const afterBurden = line.is_labor ? afterCatMarkup * laborMult : afterCatMarkup;
    return {
      ...line,
      cost,
      category_markup_pct: catPct,
      labor_burden_applied: line.is_labor ? laborMult : 1,
      marked_up_cost: afterBurden,
    };
  });

  const markedSubtotal = marked.reduce((s, l) => s + l.marked_up_cost, 0);
  const overheadAmount = markedSubtotal * (overheadPct / 100);
  const afterOverhead = markedSubtotal + overheadAmount;
  const profitAmount = afterOverhead * (profitPct / 100);
  const grandTotal = afterOverhead + profitAmount;

  // Distribute overhead + profit proportionally so each line still has a "final_cost"
  const totalLift = markedSubtotal > 0 ? grandTotal / markedSubtotal : 1;
  const finalLines = marked.map(line => ({
    ...line,
    volume_discount_applied: 0,
    final_cost: line.marked_up_cost * totalLift,
  }));

  const rawSubtotal = finalLines.reduce((s, l) => s + l.cost, 0);

  return {
    lines: finalLines,
    totals: {
      raw_subtotal: rawSubtotal,
      marked_subtotal: markedSubtotal,
      overhead_pct: overheadPct,
      overhead_amount: overheadAmount,
      profit_pct: profitPct,
      profit_amount: profitAmount,
      grand_total: grandTotal,
    },
  };
}
/**
 * Target-margin price calculator ("price for X% margin").
 * margin% is the share of the SALE that is profit: price = cost / (1 - margin).
 * Differs from markup-on-cost: a 50% margin requires a 100% markup.
 * Returns 0 for a non-positive cost; null for invalid margins (>=100 or <0).
 */
export function priceForTargetMargin(cost, marginPct) {
  const c = Number(cost);
  const m = Number(marginPct);
  if (!Number.isFinite(c) || c <= 0) return 0;
  if (!Number.isFinite(m) || m < 0 || m >= 100) return null;
  return c / (1 - m / 100);
}

import React from 'react';

// Returns the color scheme for a tier (1 = highest markup / public, descending → friends & family).
// The gradient progresses from rich slate/navy (premium customers pay more) → green/cyan (friendly tiers).
export const TIER_THEMES = [
  { bg: 'bg-slate-900', text: 'text-white', ring: 'ring-slate-900/30', soft: 'bg-slate-50', softText: 'text-slate-900', accent: 'border-slate-900' },     // 1
  { bg: 'bg-indigo-700', text: 'text-white', ring: 'ring-indigo-600/30', soft: 'bg-indigo-50', softText: 'text-indigo-900', accent: 'border-indigo-700' }, // 2
  { bg: 'bg-blue-600', text: 'text-white', ring: 'ring-blue-500/30', soft: 'bg-blue-50', softText: 'text-blue-900', accent: 'border-blue-600' },           // 3
  { bg: 'bg-sky-500', text: 'text-white', ring: 'ring-sky-400/30', soft: 'bg-sky-50', softText: 'text-sky-900', accent: 'border-sky-500' },                // 4
  { bg: 'bg-teal-500', text: 'text-white', ring: 'ring-teal-400/30', soft: 'bg-teal-50', softText: 'text-teal-900', accent: 'border-teal-500' },           // 5
  { bg: 'bg-emerald-500', text: 'text-white', ring: 'ring-emerald-400/30', soft: 'bg-emerald-50', softText: 'text-emerald-900', accent: 'border-emerald-500' }, // 6
  { bg: 'bg-amber-500', text: 'text-white', ring: 'ring-amber-400/30', soft: 'bg-amber-50', softText: 'text-amber-900', accent: 'border-amber-500' },      // 7
  { bg: 'bg-rose-500', text: 'text-white', ring: 'ring-rose-400/30', soft: 'bg-rose-50', softText: 'text-rose-900', accent: 'border-rose-500' },           // 8
];

export const getTierTheme = (tierNumber) => {
  const idx = Math.max(0, Math.min(TIER_THEMES.length - 1, (Number(tierNumber) || 1) - 1));
  return TIER_THEMES[idx];
};

export default function TierBadge({ tierNumber, size = 'md' }) {
  const theme = getTierTheme(tierNumber);
  const sizeClass = size === 'lg'
    ? 'w-12 h-12 text-lg'
    : size === 'sm'
      ? 'w-7 h-7 text-xs'
      : 'w-9 h-9 text-sm';
  return (
    <div className={`${sizeClass} ${theme.bg} ${theme.text} rounded-xl flex items-center justify-center font-bold shadow-sm ring-2 ${theme.ring} flex-shrink-0`}>
      {tierNumber}
    </div>
  );
}

